window.__SUM[18]={"LR000004":{"pair":"ADAM12 -> ITGA9","headline":"Recombinant ADAM-12 disintegrin domain binds integrin alpha9beta1 and supports cell-cell interaction, from one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant ADAM-12 and ADAM-15 disintegrin domains bind integrin alpha9beta1 in an RGD-independent manner [PMID:10944520]. The interaction supports cell adhesion and cell-cell interaction [PMID:10944520].","molecular_requirements":"The receptor is the alpha9beta1 heterodimer; the alpha9 chain alone is not tested in the abstract. Cation requirement and activation status resemble integrin-matrix interactions [PMID:10944520].","affinity_potency":[],"species_and_systems":"Recombinant disintegrin domains; species not reported in our evidence.","localisation_and_range":"ADAM12 is flagged secreted [flag]; the paper describes cell-cell adhesion [PMID:10944520].","caveats":"One paper, abstract only; species not recorded.","key_references":[{"PMID":"10944520","why":"RGD-independent binding of alpha9beta1 to ADAM-12 and -15 disintegrin domains"}],"covers":["LR000004","LR003554"]},"LR000013":{"pair":"ADAM17 -> ITGB1","headline":"Two abstract-only papers support ADAM17 interaction with beta1 integrins (alpha6beta1 by co-IP, alpha5beta1 by adhesion); IntAct has records.","interaction_type":"direct binding","direction_and_effect":"Integrins alpha6 and beta1 bind TACE (ADAM17) through its disintegrin domain, enhanced by mechanical strain [PMID:23888051]. ADAM-17 fragments also support alpha5beta1-mediated adhesion, RGD and EDTA sensitive [PMID:14970227].","molecular_requirements":"ITGB1 acts together with alpha subunits (alpha6 or alpha5) in these results; beta1 alone is not shown to suffice [PMID:23888051][PMID:14970227].","affinity_potency":[],"species_and_systems":"Co-IP in wild-type and TACE knock-out cells [PMID:23888051]; human recombinant fragments with HeLa cells [PMID:14970227].","localisation_and_range":"ADAM17 is flagged non-secreted [flag]; trans adhesion and cis co-localisation both reported [PMID:14970227].","caveats":"Both papers read as abstracts only. IntAct records (co-IP, ELISA) list ADAM17 with ITGB1 [DB:IntAct].","key_references":[{"PMID":"23888051","why":"Co-IP: alpha6/beta1 bind TACE via disintegrin domain"},{"PMID":"14970227","why":"ADAM-17 adhesion via alpha5beta1"}],"covers":["LR000013","LR003563"]},"LR000022":{"pair":"ADAM9 -> ITGA6","headline":"Murine meltrin gamma (ADAM9) binds integrin alpha6beta1 on human fibroblast lines and drives motility; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"A murine meltrin gamma-Fc fusion binds alpha6beta1 on HT1080 and Wehi 164 cells in solid-phase and antibody-inhibition experiments, and cells on it showed an eight- to tenfold increase in motility compared with laminin [PMID:10825303]. GST-disintegrin also recovered alpha6 from renal lysate [PMID:15361064].","molecular_requirements":"Alpha6 acts as alpha6beta1; binding through the ADAM9 disintegrin domain [PMID:10825303][PMID:15361064].","affinity_potency":[],"species_and_systems":"Mouse ligand fusion with human receptor-bearing cell lines [PMID:10825303]; human recombinant and renal lysate [PMID:15361064]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM9 flagged secreted [flag]; the papers use membrane-anchored ADAM9 and recombinant domains.","caveats":"Both abstract only. One further paper was abstract_insufficient and not shown.","key_references":[{"PMID":"10825303","why":"Meltrin gamma-Fc binds alpha6beta1, increases motility"},{"PMID":"15361064","why":"GST-disintegrin recovers alpha6"}],"covers":["LR000022","LR003572"]},"LR000031":{"pair":"ADIPOQ -> ADIPOR2","headline":"AdipoR2 was expression-cloned as an adiponectin receptor; one abstract-only paper plus Reactome and UniProt records.","interaction_type":"direct binding","direction_and_effect":"AdipoR1/R2 overexpression or siRNA suppression supports a role as receptors for globular and full-length adiponectin, mediating increased AMP kinase and PPAR-alpha ligand activities, fatty-acid oxidation and glucose uptake [PMID:12802337]. Activating effect.","molecular_requirements":"Reactome lists an ADIPOQ trimer bound to ADIPOR dimers [DB:Reactome]. Whether one receptor chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cDNAs and cells per curator label [PMID:12802337]. Mouse pair is non-inferred, human pair is ortholog-inferred.","localisation_and_range":"Adiponectin is flagged secreted [flag], so hormonal/endocrine action is implied; the receptor is plasma membrane per Reactome [DB:Reactome].","caveats":"Evidence is functional (gain and loss of function), not a direct binding measurement, in the abstract [PMID:12802337]. Paper covers both AdipoR1 and AdipoR2, not separated. No affinity reported. One further judged row was classed as a different entity.","key_references":[{"PMID":"12802337","why":"expression cloning of AdipoR1 and AdipoR2"}],"covers":["LR000031","LR003581"]},"LR008479":{"pair":"AFDN -> EPHA7","headline":"Database-only protein interaction between AFDN and EPHA7; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID and IntAct list a two-hybrid interaction between AFDN (MLLT4) and EPHA7 [DB:BioGRID][DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; EPHA7 flagged secreted, receptor and transmembrane [flag].","caveats":"No papers support this pair; all judged papers were different_entity or inconclusive, so it may be a partner-binding interaction rather than ligand-receptor.","key_references":[],"covers":["LR008479"]},"LR000040":{"pair":"AGRN -> MUSK","headline":"Agrin acts via a receptor complex containing MuSK; one 1996 abstract plus database records, with an accessory component required.","interaction_type":"functional only","direction_and_effect":"Agrin acts via a receptor complex that includes MuSK as well as a myotube-specific accessory component [PMID:8653787]. Database records say agrin-LRP4 induces phosphorylation and activation of MUSK [DB:UniProt]. Effect stimulatory.","molecular_requirements":"MuSK alone is not the whole receptor: a myotube-specific accessory component is needed [PMID:8653787]. Reactome and PDB 8S9P show an agrin/LRP4/MuSK complex [DB:Reactome] [DB:PDB 8S9P].","affinity_potency":[],"species_and_systems":"Species not stated in the abstract; curation tags human/human [PMID:8653787]. Both pair entries are ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only evidence; the evidence is for a complex, and the accessory component is unnamed in this paper. No affinity reported.","key_references":[{"PMID":"8653787","why":"Shows agrin acts via a MuSK-containing receptor complex with an accessory component"}],"covers":["LR000040","LR003590"]},"LR002101":{"pair":"ANGPT2 -> ITGA5","headline":"No curated paper supports ANGPT2-ITGA5; the only paper involves alphaVbeta1, and UniProt alone asserts the ITGA5 interaction.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ANGPT2 interacts with ITGA5 [DB:UniProt]; direction and effect are not reported in our evidence. The judged paper describes Ang2 interacting with alpha(v)beta(1) integrin in Tie2-deficient human glioma cells, activating FAK, ERK1/2 and JNK and increasing MMP-2 expression [PMID:16424009].","molecular_requirements":"The paper implicates alpha(v) and beta(1) integrins, not alpha5 [PMID:16424009]. BioGRID records ANGPT2-ITGB1 affinity capture-Western and reconstituted complex, which concern the beta1 chain [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human glioma cells and a murine brain xenograft in the alphaVbeta1 paper [PMID:16424009].","localisation_and_range":"ANGPT2 is flagged as secreted; ITGA5 is flagged as a receptor and not secreted [flag].","caveats":"Both rows for this pair on the one paper were judged pair_absent (verified negative for ITGA5 in that paper) [PMID:16424009]. Support rests on a UniProt annotation. Paralog issue: the alpha chain partner in the paper differs.","key_references":[{"PMID":"16424009","why":"Ang2 interacts with alphaVbeta1 integrin; ITGA5 not examined"}],"covers":["LR002101","LR005427"]},"LR002110":{"pair":"ANGPTL4 -> CDH11","headline":"ANGPTL4 binds cadherin-11 on fibroblasts and suppresses scar collagen via a beta-catenin-ID3 pathway; one full-text paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 bound cadherin-11, releasing membrane-bound beta-catenin, which entered the nucleus and upregulated ID3; ID3 interacts with scleraxis to inhibit COL1A2 and COL3A1 production [PMID:28740178]. This is an inhibitory effect on collagen expression, not receptor inhibition.","molecular_requirements":"The C-terminal fibrinogen-like fragment (cANGPTL4) is the form studied; Reactome lists ANGPTL4(164-406) in complexes with CDH11, CTNND1 and CTNNB1 [DB:Reactome] [PMID:28740178].","affinity_potency":[],"species_and_systems":"Human fibroblasts for mechanism; mouse (diabetic and ANGPTL4-knockout) and rat wounds; interaction also shown in human scar tissue [PMID:28740178].","localisation_and_range":"ANGPTL4 is described as a matricellular protein [PMID:28740178]; ligand flagged secreted [flag]. Receptor is cadherin-11, a membrane protein by the paper's description (cytoplasmic domain) [PMID:28740178].","caveats":"One paper; the assay used to show binding is not given in the excerpts. No affinity reported. Reactome also lists a membrane-bound CDH11 splice variant lacking the cytoplasmic domain [DB:Reactome].","key_references":[{"PMID":"28740178","why":"ANGPTL4 binds cadherin-11 and suppresses collagen in fibroblasts"}],"covers":["LR002110","LR005432"]},"LR009298":{"pair":"ARF1 -> CHRM3","headline":"Only BioGRID records of ARF1-CHRM3 association; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Rests on BioGRID affinity capture-Western and reconstituted complex records [DB:BioGRID]. ARF1 is an intracellular GTPase and not flagged as ligand; the judged paper was a different entity.","key_references":[],"covers":["LR009298"]},"LR000103":{"pair":"BGN -> TLR4","headline":"Biglycan is an endogenous TLR4 agonist in macrophages, shown genetically, with a microscale thermophoresis record in IntAct.","interaction_type":"functional only","direction_and_effect":"Biglycan acts in macrophages as an endogenous ligand of TLR4 and TLR2, activating p38, ERK and NF-kappaB and stimulating TNF-alpha and MIP-2 [PMID:16025156]. Effects were reduced in TLR4-mutant, TLR2-/- and MyD88-/- macrophages and abolished in TLR2-/-/TLR4-mutant cells [PMID:16025156]. Biglycan-null mice had a survival benefit in LPS- or zymosan-induced sepsis [PMID:16025156]. IntAct lists a microscale thermophoresis record P21810-O00206 citing PMID 24480070 [DB:IntAct].","molecular_requirements":"TLR2 and TLR4 each contribute, with complete loss only in the double mutant; MyD88 is needed [PMID:16025156].","affinity_potency":[],"species_and_systems":"Mouse macrophages and mice (genetic models); human and mouse pairs listed [PMID:16025156]. Abstract-only read.","localisation_and_range":"Biglycan released from the matrix or from macrophages acts as a soluble signal [PMID:16025156]; secreted flag [flag].","caveats":"Abstract-only; evidence is functional, with no affinity values in our evidence. The two TLRs are not separated except by the genetic series; the IntAct record gives no values here.","key_references":[{"PMID":"16025156","why":"biglycan signals through TLR4 and TLR2 in macrophages"}],"covers":["LR000103","LR003652"]},"LR000121":{"pair":"BMP2 -> BMPR2","headline":"BMP2 binds the type II receptor BMPR2 directly but with lower affinity than type I receptors; well supported.","interaction_type":"direct binding","direction_and_effect":"BMP-2 and BMP-7 bind BMPR-II, which signals only with a type I receptor present; the response needs both ActR-I and BMPR-II [PMID:7791754]. Mutating the low-affinity epitope 2 yields BMP-2 antagonists that inhibit its activity in C2C12 cells [PMID:10880444]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"BMPR-II binds BMP-2/-7 on its own, but binding is enhanced by type I receptor coexpression; kinase activity of both receptors is essential [PMID:7791754]. BMP-2 binding and cross-linking showed receptor complexes at the cell surface [PMID:10712517].","affinity_potency":[],"species_and_systems":"Receptor ectodomain assays and cell-surface cross-linking; SPR with recombinant BMP2 bound BMPR2 more weakly than the tight type I interactions [PMID:21702718]. Species of experiments not reported; the mouse pair is projected from human evidence.","localisation_and_range":"BMP2 flagged secreted [flag]; BMPR2 is a transmembrane receptor [PMID:7791754].","caveats":"Most confirming papers were abstract-only. Numeric Kd for BMPR2 are in a table not reproduced in our evidence.","key_references":[{"PMID":"7791754","why":"BMPR-II cloning; binds BMP-2 with type I receptors"},{"PMID":"10880444","why":"epitope mapping of BMP-2 for BMPR-II"},{"PMID":"21702718","why":"SPR with BMP2 across type I/II receptors"}],"covers":["LR000121","LR003670"]},"LR000130":{"pair":"BMP4 -> BMPR2","headline":"BMP4 binds BMPR2 in transfected COS cells, less efficiently than BMP7 and only with type I receptors; abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"BMP-4 bound BMPR-II in transfected COS-1 cells, less efficiently than OP-1/BMP-7 [PMID:7644468]. BRK-3 (BMPR2) specifically binds BMP-4 in COS cells [PMID:7673243]. BioGRID lists reconstituted-complex and affinity-capture records [DB:BioGRID 277022]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Type I receptor needed: BMPR-II binds ligands weakly alone, facilitated by type I receptors [PMID:7644468]; cross-linking was undetectable without BRK-1 or BRK-2 [PMID:7673243]. A super-high-affinity subpopulation formed only with BRK-2+BRK-3 [PMID:7673243].","affinity_potency":[],"species_and_systems":"COS-1 / COS transfectants, human skin fibroblast-derived cDNA [PMID:7644468; PMID:7673243]; curators record human.","localisation_and_range":"BMP4 flagged secreted; BMPR2 receptor [flag].","caveats":"Both papers abstract only; no affinity values. Binding is weak alone, so BMPR2 acts as a type II partner to a type I receptor.","key_references":[{"PMID":"7673243","why":"BMPR2 (BRK-3) binds BMP-4, forms type I/II complexes"},{"PMID":"7644468","why":"BMPR-II cloning; BMP-4 binds less efficiently than BMP-7"}],"covers":["LR000130","LR003679"]},"LR011200":{"pair":"BMP5 -> BMPR2","headline":"BMP5 to BMPR2 rests on GtoPdb and UniProt statements only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb]. UniProt (BMP5, P22003) states BMP5 associates with type II receptor BMPR2 together with type I receptor BMPR1A [DB:UniProt][PMID:11580864].","molecular_requirements":"Single receptor chain; coreceptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Two screened papers were abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR011200"]},"LR006787":{"pair":"BMP8A -> ACVRL1","headline":"BMP8A -> ACVRL1 rests on one GtoPdb agonist record; no papers were judged.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8A as an agonist at this receptor [DB:GtoPdb]; no paper was verified for this pair.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"BMP8A is flagged secreted [flag]; range of action not otherwise reported.","caveats":"No papers or other databases support this pair.","key_references":[],"covers":["LR006787"]},"LR000202":{"pair":"CCL16 -> CCR5","headline":"CCL16 binds CCR5 with low affinity and induces calcium flux but only marginal chemotaxis; one paper.","interaction_type":"direct binding","direction_and_effect":"CCL16 bound CCR5 with relatively low affinity and induced calcium mobilisation but marginal chemotaxis [PMID:11470772]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L1.2 cells expressing human CCR5; human ligand; abstract-only [PMID:11470772].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Single paper; CCL16 could not inhibit infection by an R5-type HIV-1 [PMID:11470772]. No affinity value reported in our evidence.","key_references":[{"PMID":"11470772","why":"CCL16 is a low-affinity CCR5 ligand"}],"covers":["LR000202"]},"LR000211":{"pair":"CCL19 -> CCRL2","headline":"CCL19 binds CCRL2 (CRAM) with CCR7-like affinity but without signalling; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Binding does not trigger calcium mobilization or migration; CCRL2 constitutively recycles via clathrin-coated pits and internalises CCL19, suggesting a scavenger or competitor role [PMID:20002784]. GtoPdb lists the type as agonist with action unknown [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 7.36","assay":"radioactive labelling binding","system":"CRAM-expressing cells","cite":"PMID:20002784"}],"species_and_systems":"Human ligand and receptor [PMID:20002784]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Single paper, abstract only; it states affinity similar to that of CCR7 without a second source. Reactome records the complex [DB:Reactome].","key_references":[{"PMID":"20002784","why":"CCL19 binding and internalisation by CRAM/CCRL2"}],"covers":["LR000211","LR003739"]},"LR000220":{"pair":"CCL24 -> CCR2","headline":"CCL24 (eotaxin-2) binds CCR2 as an antagonist, shown in one human cell-line study.","interaction_type":"direct binding","direction_and_effect":"Antagonist: eotaxin-2 is reported to be an antagonist of CCR2 [PMID:15207250]; GtoPdb also lists it as an antagonist [DB:GtoPdb].","molecular_requirements":"CCR2 expressed alone in a CHO cell line was sufficient [PMID:15207250].","affinity_potency":[{"value":"pIC50 6.2","assay":"curated binding/inhibition value","system":"CHO cell line with CCR2 in a defined genomic site","cite":"PMID:15207250"}],"species_and_systems":"Human ligand and receptor in engineered CHO cells [PMID:15207250]. The mouse pair is ortholog-inferred with no mouse data.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"Single paper, abstract only. Not an activating pair; downstream effect on cells in vivo is not reported in our evidence.","key_references":[{"PMID":"15207250","why":"CHO lines show eotaxin-2 antagonises CCR2"}],"covers":["LR000220","LR003746"]},"LR006796":{"pair":"CCL5 -> CXCR3","headline":"One curated binding paper reports weak competition binding of RANTES (CCL5) on human CXCR3; no functional test of CCL5 itself in our evidence.","interaction_type":"direct binding","direction_and_effect":"RANTES competed for 125I-IP10 binding to recombinant CXCR3 with Ki 420 nM, far weaker than IP10 (0.14 nM) [PMID:9660793]. GtoPdb lists it as a full agonist [DB:GtoPdb], but the paper's abstract only shows agonist/antagonist behaviour for eotaxin, not CCL5.","molecular_requirements":"Not reported in our evidence; single receptor chain, no co-receptor discussed.","affinity_potency":[{"value":"Ki 420 nM","assay":"competition binding vs 125I-IP10 (table row)","system":"recombinant human CXCR3 in CHO cells","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and human receptor, recombinant CXCR3 in CHO cells [PMID:9660793].","localisation_and_range":"CCL5 is flagged secreted and CXCR3 transmembrane [flag], so paracrine signalling is implied by annotation only.","caveats":"Affinity is weak relative to the cognate CXCR3 chemokines; the quote is a table row read in a browser, not verified. Efficacy of CCL5 at CXCR3 is not shown in the paper text we have.","key_references":[{"PMID":"9660793","why":"CXCR3 pharmacology; RANTES competition Ki 420 nM"}],"covers":["LR006796"]},"LR003889":{"pair":"CCN2 -> ITGAM","headline":"Two papers report that integrin alphaMbeta2 mediates monocyte adhesion to CCN2 (CTGF) and that the alphaM I domain binds CCN2.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaMbeta2 is an adhesion receptor for CCN2 on monocytes. THP-1 cells and monocytes adhered to CTGF-coated wells in an activation-dependent manner, mainly through alphaM beta2 [PMID:12036876]. Signalling outcome is not reported in our evidence.","molecular_requirements":"The alphaM I domain is sufficient for binding: a GST-alphaMI fusion bound CTGF and the CCN2 H2 peptide (TSVKTYRAKFCGV) [PMID:12036876][PMID:12736251]. Heparan sulfate proteoglycans were tested as co-receptors for Cyr61 (CCN1), not reported for CCN2 [PMID:12036876]. Full functional receptor is the alphaM-beta2 heterodimer.","affinity_potency":[],"species_and_systems":"Human THP-1 cells and peripheral blood monocytes; HEK293 expressing alphaMbeta2 (for Cyr61); GST-fusion binding assays [PMID:12036876][PMID:12736251].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers. Adhesion to coated protein suggests matrix-bound presentation.","caveats":"Both papers read as abstracts only. Much of the work centres on CCN1 (Cyr61); CCN2 data are mostly parallel observations. No affinity values are reported in our evidence.","key_references":[{"PMID":"12036876","why":"Monocyte adhesion to CTGF mediated by alphaMbeta2; alphaM I domain binds CTGF"},{"PMID":"12736251","why":"H2 peptide in CCN2 binds alphaM I domain"}],"covers":["LR000383","LR003889"]},"LR007957":{"pair":"CD80 -> NGFR","headline":"CD80 and NGFR rest on database interaction records only, with no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a direct interaction by surface plasmon resonance and a protein-array record, both from large-scale studies [DB:IntAct]. Species not reported in our evidence.","localisation_and_range":"Both partners are annotated as receptors [flag]; CD80 is flagged secreted and transmembrane [flag].","caveats":"No paper judged confirmed; the one judged row is abstract_insufficient. Support is only from IntAct records [DB:IntAct]. Treat as unvalidated.","key_references":[],"covers":["LR007957"]},"LR005599":{"pair":"CDH1 -> FGFR1","headline":"Curators verified absence: the paper concerns Cdh2 and FGFR1, not Cdh1; database co-IP records exist.","interaction_type":"conflicting","direction_and_effect":"Cdh2 co-immunoprecipitated with and stabilised FGFR1 in mouse epiblast stem cells; Cdh1 overexpression did not restore pluripotency gene expression [PMID:26420260].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse epiblast stem cells and ESCs [PMID:26420260]; human pair ortholog-inferred.","localisation_and_range":"Membrane proteins [flag].","caveats":"Two papers judged pair_absent. IntAct anti-bait co-IP and BioGRID reconstituted complex records are listed [DB:IntAct] [DB:BioGRID]; direct Cdh1 binding not shown.","key_references":[{"PMID":"26420260","why":"Cdh2, not Cdh1, interacts with FGFR1"}],"covers":["LR002301","LR005599"]},"LR003799":{"pair":"CDH1 -> ITGAE","headline":"E-cadherin is a direct ligand for integrin alphaE (CD103) beta7, well supported by binding, adhesion, structure and Reactome.","interaction_type":"direct binding","direction_and_effect":"E-cadherin-Fc binds directly to soluble recombinant alphaEbeta7; IELs or transfected cells adhere to it and antibodies block [PMID:9425167]. T-cell/epithelial adhesion is mediated by E-cadherin and alphaEbeta7 [PMID:7969453]; E-cadherin expression on pancreatic cancer cells affected T-cell adhesion [PMID:12434297]. UniProt: ITGAE/ITGB7 is a receptor for E-cadherin [DB:UniProt].","molecular_requirements":"alphaE pairs with beta7; this entry names the alphaE chain only [PMID:9425167]. P-cadherin needed over 100-fold more fusion protein [PMID:9425167].","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:9425167] [PMID:12434297]; mouse pair ortholog-inferred. PDB 9P99 has a structure [DB:PDB 9P99].","localisation_and_range":"Membrane-bound; contact-dependent adhesion.","caveats":"Mostly abstract-only. PMID 9233649 was confirmed on a background sentence about a beta7 mapping study.","key_references":[{"PMID":"9425167","why":"Direct E-cadherin-alphaEbeta7 binding"},{"PMID":"7969453","why":"Epithelial-IEL adhesion"},{"PMID":"12434297","why":"CD103 and E-cadherin in T-cell adhesion"}],"covers":["LR000290","LR003799"]},"LR000301":{"pair":"CHAD -> ITGB1","headline":"Chondroadherin engages beta1 integrins (as alpha2beta1); ITGB1 evidence is via the heterodimer.","interaction_type":"direct binding","direction_and_effect":"Annotated stimulatory [flag]. Anti-beta1 antibody reduced adhesion of chondrocytes to chondroadherin by 2/3 at 100 \u03bcg/ml, indicating beta1 integrins are involved; alpha2beta1 was identified as a chondroadherin-binding integrin [PMID:9281592].","molecular_requirements":"ITGB1 acts as part of alpha2beta1, requiring ITGA2; divalent cations Mg2+ or Mn2+ needed, not Ca2+ [PMID:9281592].","affinity_potency":[],"species_and_systems":"Bovine chondrocytes in the abstract and excerpts; curator note cites human fibroblasts [PMID:9281592].","localisation_and_range":"Matrix ligand flagged secreted [flag].","caveats":"Evidence is from a single 1997 paper read as abstract (full-text excerpts available). Chain-only support: the paper identifies the heterodimer; antibody inhibition was partial. No affinity reported.","key_references":[{"PMID":"9281592","why":"Anti-beta1 inhibition and alpha2beta1 identification"}],"covers":["LR000301","LR003807"]},"LR000310":{"pair":"CNTN2 -> CNTNAP2","headline":"Direct, specific CNTN2-CNTNAP2 ectodomain binding with low nanomolar affinity, plus mouse knockout evidence.","interaction_type":"direct binding","direction_and_effect":"CNTNAP2 and CNTN2 ectodomains bind directly and specifically, with low nanomolar affinity [PMID:27621318]. Association of TAG-1 with Caspr2 is essential for juxtaparanodal organisation [PMID:12975355].","molecular_requirements":"Ectodomains are sufficient for binding [PMID:27621318]. CNTNAP2 domain architecture is mapped by electron microscopy [PMID:27621318].","affinity_potency":[],"species_and_systems":"Human ectodomains [PMID:27621318]; TAG-1 knockout mice [PMID:12975355]. Mouse pair inferred from human.","localisation_and_range":"CNTN2 flagged secreted [flag]; in axons the proteins act at juxtaparanodes [PMID:12975355].","caveats":"Both papers abstract-only; affinity is stated only as 'low nanomolar' with no exact value in our evidence.","key_references":[{"PMID":"27621318","why":"Direct ectodomain binding, low nanomolar"},{"PMID":"12975355","why":"In vivo requirement at juxtaparanodes"}],"covers":["LR000310","LR003816"]},"LR006895":{"pair":"COL1A2 -> ITGA11:ITGB1","headline":"Weak: one abstract-only paper describes ITGA11 as a type I collagen receptor in pancreatic stellate cells.","interaction_type":"functional only","direction_and_effect":"ITGA11 is described as the type I collagen receptor, studied for tumour-stroma interaction in pancreatic cancer [PMID:30808244].","molecular_requirements":"ITGB1 pairing is not shown in this paper; not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pancreatic stellate cells and PDAC stroma [PMID:30808244].","localisation_and_range":"Complex entity flagged transmembrane, not a receptor, with Adhesion-Adhesion class [flag].","caveats":"Abstract-only; assay is functional, not binding. The evidence sentence is background on stellate cells. Four rows review_only. Chain-level: COL1A1 and COL1A2 are one heterotrimer.","key_references":[{"PMID":"30808244","why":"ITGA11 as collagen I receptor in PDAC stroma"}],"covers":["LR006895"]},"LR006994":{"pair":"COL8A1 -> ITGA10:ITGB1","headline":"COL8A1-ITGB1 interaction reported in colorectal and pancreatic cancer abstracts; the ITGA10 chain itself is not tested.","interaction_type":"functional only","direction_and_effect":"In colorectal cancer, COL8A1 secreted from THBS2+ CAFs is reported to directly interact with ITGB1 on resistant malignant cells, activating PI3K-AKT signaling and promoting EMT and oxaliplatin resistance [PMID:39732719]. In PDAC cells, ITGB1 and DDR1 activation, PI3K/AKT and NF-\u03baB signaling occurred downstream of COL8A1 [PMID:36375776].","molecular_requirements":"Evidence names ITGB1 only; the ITGA10 subunit is not mentioned in our evidence, so the alpha-chain requirement is not reported. Full-text excerpts of PMID:39732719 describe CellChat COL8A1-ITGB1 inference, spatial colocalisation and molecular docking, not subunit requirements [PMID:39732719].","affinity_potency":[],"species_and_systems":"Human colorectal cancer and PDAC cells; both papers read as abstract, with excerpts for PMID:39732719.","localisation_and_range":"Ligand flagged secreted [flag]; CAF-to-tumor-cell paracrine/matrix signaling in the CRC study [PMID:39732719].","caveats":"Complex-level support rests on ITGB1 alone; part of the support is computational (CellChat, spatial colocalisation, docking). Four further rows are review-only.","key_references":[{"PMID":"39732719","why":"COL8A1 from CAFs interacts with ITGB1 in CRC"},{"PMID":"36375776","why":"COL8A1 activates ITGB1/DDR1 signaling in PDAC"}],"covers":["LR006994"]},"LR007966":{"pair":"CRLF2 -> CRLF2:IL7R","headline":"CRLF2 to IL7R complex is supported only by PDB structures; no confirmed paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"A crystal structure of human TSLP in complex with TSLPR and IL-7Ralpha exists [DB:PDB 5J11], plus TSLP:TSLPR with mouse IL-7Ralpha [DB:PDB 5J12]. Direction and effect are not reported in our evidence.","molecular_requirements":"The structure contains TSLP, TSLPR (CRLF2) and IL-7Ralpha, so the receptor is a heteromer needing both chains [DB:PDB 5J11].","affinity_potency":[],"species_and_systems":"Human proteins in X-ray structures; 5J12 uses mouse IL-7Ralpha [DB:PDB 5J12].","localisation_and_range":"CRLF2 is flagged secreted and receptor [flag].","caveats":"The two judged papers concerned a different entity. The listed ligand is itself a receptor chain, and TSLP is the actual ligand here; this entry is a complex-membership record.","key_references":[],"covers":["LR007966"]},"LR003898":{"pair":"CXCL10 -> CCR3","headline":"CXCL10 competes with eotaxin for CCR3 and acts as an antagonist; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"CXCL10 (IP10) competed for eotaxin binding to CCR3 and inhibited CCR3-mediated signalling, without inducing CCR3 internalisation, i.e. antagonist behaviour [PMID:11110785]. GtoPdb lists it as an antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of ligand and receptor not clearly stated; curator labels not given in the shown fields. Mouse pair is projected from human evidence.","localisation_and_range":"CXCL10 is flagged secreted and CCR3 transmembrane [flag].","caveats":"Read from the abstract only. No affinity value reported in our evidence.","key_references":[{"PMID":"11110785","why":"CXCR3 agonists act as CCR3 antagonists"}],"covers":["LR000392","LR003898"]},"LR000400":{"pair":"CXCL12 -> CXCR3","headline":"Only weak, abstract-level evidence: CXCR3 has 'very modest affinity' for SDF-1alpha; activation by CXCL12 is not shown.","interaction_type":"direct binding","direction_and_effect":"The paper reports that CXCR3 has very modest affinity for SDF-1alpha and little or no affinity for other CXC chemokines, versus Ki 0.14 and 4.9 nM for IP10 and MIG [PMID:9660793]. GtoPdb lists it as Agonist, full agonist [DB:GtoPdb], but the abstract does not show CXCL12-induced activation.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKi 6.4","assay":"competition binding","system":"CXCR3 heterologously expressed in transfected cells","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and receptor in transfected cells; endogenous receptor on activated T cells was described as similar; mouse pair projected from human [PMID:9660793].","localisation_and_range":"CXCL12 is flagged secreted and CXCR3 transmembrane [flag].","caveats":"Abstract only. The curator calls this weak and likely non-physiological. The 'agonist' label rests on GtoPdb and the curator, not on a demonstrated response in the paper.","key_references":[{"PMID":"9660793","why":"CXCR3 pharmacology; modest SDF-1alpha affinity"}],"covers":["LR000400","LR003905"]},"LR003988":{"pair":"EFNA4 -> EPHA7","headline":"No verified paper; one IntAct comigration record supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists a 'direct interaction by comigration in sds page' record for EFNA4 and EPHA7 [DB:IntAct]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; the human pair is ortholog-inferred.","localisation_and_range":"Both flagged secreted and transmembrane [flag].","caveats":"All judged papers were review-only or abstract-insufficient; evidence is a single database assay type.","key_references":[],"covers":["LR000497","LR003988"]},"LR003997":{"pair":"EFNA5 -> EPHA8","headline":"Functional evidence only: EphA8-driven adhesion depends on ephrin A binding; EFNA5 itself is not named as the tested ligand.","interaction_type":"functional only","direction_and_effect":"EphA8 expression enhanced cell adhesion to fibronectin via integrins, and this required ephrin A binding to the EphA8 extracellular domain [PMID:11416136]. Annotated effect is stimulatory.","molecular_requirements":"Adhesion needed the EphA8 extracellular domain plus the juxtamembrane segment, but not kinase activity (a kinase-inactive mutant still promoted attachment) [PMID:11416136].","affinity_potency":[],"species_and_systems":"NIH 3T3 and HEK293 cells; ligand and receptor species not specified. The pair is listed for human (projected from ortholog evidence) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Read from the abstract only. 'Ephrin A' is not resolved to EFNA5; ephrin A5-Fc was used only to strip endogenous ligands from cells [PMID:11416136]. No binding data in our evidence.","key_references":[{"PMID":"11416136","why":"EphA8 adhesion depends on ephrin A binding to the ectodomain"}],"covers":["LR000506","LR003997"]},"LR004000":{"pair":"EFNB1 -> EPHB1","headline":"Functional ligand-stimulation evidence in mouse cells plus database statements of high-affinity binding; no primary binding paper shown.","interaction_type":"functional only","direction_and_effect":"Stimulating endogenous EphB1 with its ligand ephrinB1 in P19 embryonal carcinoma cells increased EphB1 association with Grb7 [PMID:12223469]. UniProt states ephrin-B1 shows high affinity for EPHB1 [DB:UniProt]. Annotated stimulatory.","molecular_requirements":"Grb7 binding requires EphB1 tyrosine autophosphorylation, with Tyr-928 as the main site [PMID:12223469].","affinity_potency":[],"species_and_systems":"Mouse P19 cells [PMID:12223469]. Pair listed for human (not ortholog-inferred) and mouse (ortholog-inferred). IntAct has a solid phase assay record [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"The paper is about Grb7 binding to EphB1, abstract only; ligand binding itself was not measured there. UniProt cites PMID 7973638 and 8070404, which are not in our judged papers [DB:UniProt].","key_references":[{"PMID":"12223469","why":"Ephrin-B1 stimulation of endogenous EphB1 in P19 cells"}],"covers":["LR000509","LR004000"]},"LR005797":{"pair":"EGFL7 -> NOTCH3","headline":"Secreted EGFL7 binds human NOTCH3 by co-IP and acts as a Notch antagonist; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Secreted EGFL7 binds a Notch region involved in ligand-mediated activation and acts as an antagonist of Notch signalling; EGFL7 expression in neural stem cells decreased Notch-specific signalling [PMID:19503073].","molecular_requirements":"Not reported in our evidence beyond Notch receptors binding EGFL7 via EGF-like domains; control receptors with EGF-like domains did not interact [PMID:19503073].","affinity_potency":[],"species_and_systems":"Endogenous human NOTCH3 co-immunoprecipitated recombinant human EGFL7 in cell lines; tagged proteins in HEK293 cells [PMID:19503073]. BioGRID lists a two-hybrid record [DB:BioGRID].","localisation_and_range":"EGFL7 is secreted [flag] and the Notch receptor is transmembrane [flag]; binding was retained with the two proteins on apposing cells [PMID:19503073].","caveats":"One paper supports all three Notch paralogs, and this row has no independent confirmation. No affinity reported in our evidence.","key_references":[{"PMID":"19503073","why":"EGFL7 binds Notch1-4 and antagonises Notch signalling"}],"covers":["LR002529","LR005797"]},"LR011998":{"pair":"ENG -> ACVRL1:BMPR2","headline":"ENG with ACVRL1:BMPR2 rests only on BioGRID and UniProt records; no curated papers.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as Receptor-Receptor, stimulatory. BioGRID lists BMPR2-ENG affinity capture-Western [DB:BioGRID]; UniProt states endoglin interacts with ACVRL1 [DB:UniProt].","molecular_requirements":"The complex is ACVRL1 plus BMPR2; the databases show ENG-BMPR2 and ENG-ACVRL1 contacts separately [DB:BioGRID][DB:UniProt].","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; human entities.","localisation_and_range":"ENG, ACVRL1 and BMPR2 are all flagged receptors [flag].","caveats":"No curator-verified papers (3 pending). Database support only; receptor-receptor association, not clearly ligand-receptor.","key_references":[],"covers":["LR011998"]},"LR008767":{"pair":"F12 -> GP1BA","headline":"Factor XII binds platelet GPIb-IX-V (GP1BA) and factor XIIa inhibits thrombin-induced aggregation; abstract-level.","interaction_type":"direct binding","direction_and_effect":"Factor XII binds platelets through GP Ibalpha, and factor XIIa, but not zymogen, is required to inhibit thrombin-induced aggregation [PMID:10801853]. Factor XII displaced biotin-HK binding, blocking 50% at 50 nm [PMID:10801853].","molecular_requirements":"Binding is to the GPIb-IX-V complex; proteolytic activation exposing the heavy chain is required for inhibition, but catalytic activity is not [PMID:10801853].","affinity_potency":[],"species_and_systems":"Human factor XII and platelets [PMID:10801853]. BioGRID reconstituted complex [DB:BioGRID].","localisation_and_range":"Plasma protein acting at the platelet surface; GP1BA flagged transmembrane [flag].","caveats":"Abstract-only; the curated evidence sentence concerns HK, not factor XII. Factor XIIa was used at 0.37 microm; no affinity reported.","key_references":[{"PMID":"10801853","why":"Factor XII binding to GPIb-IX-V inhibits thrombin-induced aggregation"}],"covers":["LR008767"]},"LR005878":{"pair":"FAM3B -> FGFR3","headline":"FAM3B is reported as an FGFR ligand in one Xenopus paper; FGFR3-specific evidence is thin.","interaction_type":"functional only","direction_and_effect":"The paper shows FAM3B as an FGFR ligand in Xenopus, with ERK activation via FGFR1 [PMID:33975953]. Purified human FAM3B was incubated with Fc-tagged human FGFR1-4 ectodomains, with FGFR3-Ecto-Fc one of the panels; the excerpts do not show the FGFR3 result itself [PMID:33975953].","molecular_requirements":"FGFR1 kinase-inactive mutant with intact ectodomain still bound FAM3B; no co-receptor requirement reported [PMID:33975953]. Whether FGFR3 acts alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus embryos, HEK293T cells and recombinant human FAM3B; curation row labels species human [PMID:33975953].","localisation_and_range":"FAM3B is secreted [flag] and detected in HEK293T medium [PMID:33975953].","caveats":"Single paper. The abstract does not say which of FGFR1-4 binds; all four rows rest on a family-level claim, and the main system is Xenopus [PMID:33975953]. No affinity reported. FGF family paralog overlap is possible.","key_references":[{"PMID":"33975953","why":"FAM3B binds FGFR ectodomain and activates ERK in Xenopus/HEK293T"}],"covers":["LR002611","LR005878"]},"LR005896":{"pair":"FGF2 -> ITGAV","headline":"FGF2 binds integrin alphavbeta3 (SPR) and binding-defective FGF2 mutants antagonise FGF2 signalling; evidence is for the heterodimer.","interaction_type":"direct binding","direction_and_effect":"WT FGF2 bound immobilised soluble \u03b1v\u03b23 by SPR; FGF2 mutants K119E/R120E and K125E have reduced integrin binding, fail to drive ERK1/2 activation and DNA synthesis, and suppress WT FGF2 signalling in endothelial cells, acting as antagonists [PMID:28302677]. UniProt states ITGAV:ITGB3 binds FGF2 and this is essential for FGF2 signalling [DB:UniProt].","molecular_requirements":"The data concern the \u03b1v\u03b23 heterodimer, not \u03b1v alone; K562 adhesion also suggested binding to \u03b15\u03b21 [PMID:28302677]. FGF2 was modelled as able to bind FGFR1 and \u03b1v\u03b23 simultaneously [PMID:28302677].","affinity_potency":[{"value":"Kd 7.75 \u00d7 10\u22128 M","assay":"SPR, WT FGF2 on immobilised soluble \u03b1v\u03b23","system":"recombinant, in vitro","cite":"PMID:28302677"},{"value":"Kd 1.1 \u00d7 10\u22126 M","assay":"SPR, K125E FGF2 mutant on \u03b1v\u03b23","system":"recombinant, in vitro","cite":"PMID:28302677"}],"species_and_systems":"Cell work used NIH3T3 mouse fibroblasts and HUVECs; ligand and receptor species are recorded as human [PMID:28302677]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF2 is flagged secreted and the receptor a membrane integrin [flag]; paracrine ligand to cell-surface integrin is implied, not tested as such.","caveats":"The curator evidence sentence is background citing earlier work; this paper's own data are the SPR and mutant results. Docking is predictive only, and the authors note mutations could act through conformational changes. Paper read at abstract level for the curated row.","key_references":[{"PMID":"28302677","why":"SPR Kd of FGF2 for \u03b1v\u03b23 and integrin-binding-defective antagonist mutants"}],"covers":["LR002630","LR005896"]},"LR005959":{"pair":"GHRH -> GHSR","headline":"GHRH acts as an agonist at the ghrelin receptor GHS-R1a in one abstract-only study; not its canonical receptor.","interaction_type":"direct binding","direction_and_effect":"hGHRH(1-29)NH2 induced dose-dependent calcium mobilization in GHS-R1a-transfected HEK293 cells but not wild-type cells; radioligand binding and cross-linking indicated mediation by GHS-R1a. It activated inositol phosphate signalling, potentiated the ghrelin maximal response and increased 125I-ghrelin binding capacity [PMID:19088192].","molecular_requirements":"GHS-R1a isoform was used; GHRH-receptor antagonists JV-1-42 and JMR-132 also antagonized GHS-R1a [PMID:19088192].","affinity_potency":[],"species_and_systems":"Human GHRH on HEK293 and CHO cells expressing GHS-R1a [PMID:19088192]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand secreted, receptor transmembrane [flag].","caveats":"Single paper, abstract only; no affinity reported; no database records. Independent confirmation not in our evidence.","key_references":[{"PMID":"19088192","why":"GHRH agonist activity at GHS-R1a"}],"covers":["LR002694","LR005959"]},"LR005968":{"pair":"GPNMB -> CD44","headline":"GPNMB signals through CD44 to damp astrocyte inflammation; functional knockout evidence, not binding data.","interaction_type":"functional only","direction_and_effect":"Recombinant GPNMB attenuated cytokine-induced inflammatory mediators in astrocyte cultures, and this was lost in CD44 knockout primary mouse astrocytes, so the anti-inflammatory effect is CD44-dependent [PMID:29519253]. Curators label it antagonist, meaning it dampens inflammation.","molecular_requirements":"CD44 is required for the effect [PMID:29519253]. Which GPNMB form acts: the paper describes a soluble peptide released by ADAM10 or other protease cleavage, but this is background [PMID:29519253].","affinity_potency":[],"species_and_systems":"Mouse astrocytes (IMA2.1 line and primary cells, including CD44 knockout) treated with recombinant GPNMB; expression data also from human Parkinson's disease substantia nigra and MPTP mice [PMID:29519253]. Human pair listed as ortholog-inferred.","localisation_and_range":"GPNMB is flagged as secreted [flag]; the paper states it is a transmembrane protein that is cleaved to release a soluble peptide [PMID:29519253]. CD44 is flagged as both secreted and transmembrane [flag].","caveats":"Direct GPNMB-CD44 binding is stated only as background in the abstract ('can bind'), not shown in this paper. Full text available, but only one paper is listed.","key_references":[{"PMID":"29519253","why":"CD44 knockout astrocytes lose the GPNMB anti-inflammatory effect"}],"covers":["LR002703","LR005968"]},"LR011989":{"pair":"GREM2 -> GDF5","headline":"Gremlin-2 binds GDF5 directly, shown by a 2.9-\u00c5 crystal structure and SPR; Gremlin-2 acts as a BMP antagonist.","interaction_type":"direct binding","direction_and_effect":"Grem2 is a secreted BMP antagonist of the DAN family; it occupies both the type I and type II receptor-binding motifs on GDF5, consistent with inhibition [PMID:27524626].","molecular_requirements":"Two Grem2 dimers bind perpendicularly to each GDF5 dimer; Grem2's N terminus changes conformation on binding [PMID:27524626].","affinity_potency":[{"value":"KD 146 nM","assay":"surface plasmon resonance","system":"Grem2 with GDF5 (moderate-affinity ligand; BMP2 KD 9 nM in the same assay)","cite":"PMID:27524626"}],"species_and_systems":"Recombinant proteins and crystallography; the species of the proteins is not stated in our excerpts [PMID:27524626]. Dossier pair is human.","localisation_and_range":"Grem2 is described as secreted [PMID:27524626]; GDF5 carries both secreted and transmembrane annotation flags [flag].","caveats":"The curated paper was read as abstract plus full-text excerpts. GDF5 is the ligand being bound here, so it is not a conventional receptor; direction follows the database labelling.","key_references":[{"PMID":"27524626","why":"Grem2-GDF5 structure at 2.9 \u00c5 and SPR affinity"}],"covers":["LR011989"]},"LR008659":{"pair":"HGF -> ITGB1","headline":"No verified evidence for direct HGF-ITGB1 binding; only a Reactome complex record and unusable papers.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. Reactome lists a complex of HGF with phosphorylated MET dimer, TNS4 and ITGB1 [DB:Reactome].","molecular_requirements":"In the Reactome record ITGB1 appears within a MET-containing complex; whether ITGB1 binds HGF itself is not reported in our evidence [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"HGF is flagged secreted [flag]; the Reactome complex is at the plasma membrane [DB:Reactome].","caveats":"No curator-confirmed paper: judged rows were one review-only and three abstract-insufficient. Support comes only from a Reactome complex in which MET, not ITGB1, binds TNS4; this is a pathway-context association, not demonstrated ligand-receptor binding.","key_references":[],"covers":["LR008659"]},"LR005977":{"pair":"HGF -> NRP2","headline":"HGF binds NRP2 according to one abstract-level paper; NRP2 appears to act as a co-receptor with c-Met.","interaction_type":"direct binding","direction_and_effect":"NRP2 binds HGF; knockdown of NRP1 or NRP2 in HUVECs decreased HGF-induced c-Met phosphorylation and signalling [PMID:18065694]. NRP2 acts as a co-receptor potentiating c-Met signalling [PMID:18065694].","molecular_requirements":"The N-terminal domain of HGF is involved in the binding [PMID:18065694]. Blocking antibodies had an enhanced effect when binding to both neuropilins was disrupted [PMID:18065694].","affinity_potency":[],"species_and_systems":"Human proteins and HUVECs; the in vivo mouse Matrigel result was reported for NRP1, not NRP2 [PMID:18065694].","localisation_and_range":"NRP2 is annotated as a transmembrane receptor [flag].","caveats":"Single paper, read as an abstract only. No affinity reported. Direct-binding method details are not available in our evidence.","key_references":[{"PMID":"18065694","why":"HGF binds NRP1 and NRP2; knockdown reduces c-Met signalling"}],"covers":["LR002712","LR005977"]},"LR005986":{"pair":"HMGB1 -> LY96","headline":"Strong direct binding of disulfide HMGB1 to MD-2 (Kd 12 nM, SPR) that drives TLR4 signalling; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"MD-2 binds the cytokine-inducing disulfide isoform of HMGB1 to the exclusion of other isoforms. MD-2-deficient mice and MD-2 silencing in macrophages show it is required for HMGB1-dependent TLR4 signalling. Peptide P5779 antagonises the MD-2-HMGB1 interaction without blocking LPS responses [PMID:25559892]. Reactome records HMGB1 binding TLR4:LY96 [DB:Reactome].","molecular_requirements":"Only the disulfide isoform binds; fully reduced, H2S-modified or sulfonyl HMGB1 had more than 1,000-fold reduced MD-2 binding, and cysteine 106 modification abolished binding. HMGB1 did not bind TLR4 directly without MD-2 [PMID:25559892].","affinity_potency":[{"value":"apparent Kd 12 nM","assay":"Biacore SPR","system":"disulfide HMGB1 with MD-2","cite":"PMID:25559892"}],"species_and_systems":"Recombinant proteins plus mouse macrophages (RAW 264.7) and MD-2-deficient mice [PMID:25559892]. Curated as human ligand with mouse receptor; the mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; MD-2 is an extracellular TLR4 adaptor [PMID:25559892].","caveats":"Isoform-specific, so total HMGB1 expression does not predict signalling. Single primary paper.","key_references":[{"PMID":"25559892","why":"Disulfide HMGB1 binds MD-2; P5779 antagonist"}],"covers":["LR002738","LR005986"]},"LR008569":{"pair":"HRAS -> CAV1","headline":"No verified evidence; one IntAct imaging record only, and HRAS is not annotated as a ligand.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists an imaging-technique interaction record [DB:IntAct]; species of the experiment is not reported in our evidence.","localisation_and_range":"HRAS carries no secreted flag [flag]; localisation of the interaction is not reported in our evidence.","caveats":"No curator-verified paper: one row judged different_entity and three abstract_insufficient. This rests on a single database record.","key_references":[],"covers":["LR008569"]},"LR008389":{"pair":"IL1RAPL2 -> PTPRS","headline":"IL1RAPL2 binding to PTPRS detected in a human interactome screen and listed as SPR-validated; single paper.","interaction_type":"direct binding","direction_and_effect":"In the screen the authors detected binding of IL1RAPL2 to PTPRD and PTPRS; Table 1 lists IL1RAPL2-PTPRS as SPR-validated [PMID:32822567]. Effect direction is not reported in our evidence.","molecular_requirements":"Ectodomain-Fc fusions were used; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ectodomain-Fc proteins, ELISA screen with SPR validation [PMID:32822567].","localisation_and_range":"PTPRS is flagged secreted and transmembrane [flag].","caveats":"One primary paper, no affinity, no functional data, no database support.","key_references":[{"PMID":"32822567","why":"Interactome screen reporting IL1RAPL2-PTPRS"}],"covers":["LR008389"]},"LR008578":{"pair":"ITGAL:ITGB2 -> F11R","headline":"LFA-1 (ITGAL:ITGB2) binding to F11R (JAM-A) is asserted by Reactome and UniProt; no paper judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says ITGAL/ITGB2 is a receptor for F11R [DB:UniProt]; Reactome has a binding reaction for LFA-1 and JAM-A [DB:Reactome].","molecular_requirements":"UniProt notes F11R interacts with ITGAL via its I-domain [DB:UniProt].","affinity_potency":[],"species_and_systems":"No experimental paper judged for this pair; species is human per the record.","localisation_and_range":"Both partners carry receptor flags and VCAM1 is flagged transmembrane [flag]; contact-mediated adhesion is implied by the plasma membrane complexes listed [DB:Reactome].","caveats":"Database support only; three pending papers not judged.","key_references":[],"covers":["LR008578"]},"LR007975":{"pair":"JAG2 -> VASN","headline":"No verified paper; support rests on IntAct records only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct records coimmunoprecipitation, solid-phase assay and SPR for the pair [DB:IntAct].","localisation_and_range":"JAG2 flagged as not secreted; VASN not transmembrane [flag].","caveats":"The one judged paper was abstract_insufficient. IntAct records cite PMID 35922511 and PMID 33961781, which are not curator-verified for this pair.","key_references":[],"covers":["LR007975"]},"LR011002":{"pair":"LAMA3 -> ITGA2:ITGB1","headline":"No verified paper; Reactome asserts alpha2beta1 binds laminin-332.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Complex of ITGA2 and ITGB1; the Reactome reaction is integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","affinity_potency":[],"species_and_systems":"Reactome human binding reaction citing PMID 9645947 [DB:Reactome R-HSA-349626].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand.","caveats":"Three papers were abstract_insufficient; support rests on a database assertion at the laminin-332 trimer level.","key_references":[],"covers":["LR011002"]},"LR001003":{"pair":"LAMB1 -> ITGB4","headline":"Laminin beta1-containing laminins bind integrin alpha6beta4; Kd 25 nM recombinant plus radioligand and flow-adhesion studies.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha6beta4 [PMID:16413178]. Radioligand-binding and adhesion assays showed alpha6beta4 is a receptor for laminin 1, 2, 4 and 5 [PMID:7721947]. Laminin supported alpha6beta4-positive cell attachment under shear, blocked by an anti-alpha6 antibody [PMID:7699012]. Annotated stimulatory.","molecular_requirements":"The binder is the alpha6beta4 heterodimer and the ligand a whole laminin heterotrimer; ITGB4 and LAMB1 were not tested alone [PMID:16413178][PMID:7699012].","affinity_potency":[{"value":"Kd 25 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha6beta4)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; rat 804G bladder epithelial cells with laminin of unstated origin [PMID:7721947]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGB4 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"The 804G system is rat and laminin origin is unstated [PMID:7721947]. The flow-assay paper is abstract-only [PMID:7699012]. Two further reads were abstract_insufficient and one review_only.","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta4 for laminin-511/521"},{"PMID":"7721947","why":"Radioligand binding of alpha6beta4 to laminin isoforms"},{"PMID":"7699012","why":"alpha6beta4 adhesion to laminin under flow"}],"covers":["LR001003","LR004422"]},"LR001012":{"pair":"LAMC1 -> ITGB1","headline":"LAMC1 (in several laminins) binds beta1 integrins; Kd 3.4 nM in recombinant assay plus adhesion-blocking studies.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha3beta1 in solid-phase assays [PMID:16413178]. Platelet adhesion to platelet laminin was largely inhibited by anti-beta1 and anti-alpha6 antibodies [PMID:10585296]. A549 adhesion to laminin-10/11 was inhibited by anti-alpha3 or anti-beta1 antibodies [PMID:9624186]. Annotated effect is Stimulatory [flag].","molecular_requirements":"Binders are alpha-beta1 heterodimers (alpha3beta1, alpha6beta1, alpha7beta1 across papers), never ITGB1 alone; ligands are assembled laminin heterotrimers, so LAMC1 is one chain [PMID:16413178]. PDB 7CEC lists chains of P11047 and P05556 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 3.4 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha3beta1 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; human platelets [PMID:10585296]; human A549 cells [PMID:9624186]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. The other papers were read as abstracts only and use antibody blocking (functional). Eight confirmed rows but only four papers are shown; PMID:11278916 is also listed.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-511/521"},{"PMID":"9624186","why":"Anti-beta1 blocks A549 adhesion to laminin-10/11, abstract only"},{"PMID":"10585296","why":"Anti-beta1 blocks platelet adhesion to laminin, abstract only"}],"covers":["LR001012","LR004430"]},"LR001021":{"pair":"LEP -> LEPR","headline":"Well-supported direct leptin-LEPR binding with cryo-EM structure and mapped binding domain; leptin activates LEPR.","interaction_type":"direct binding","direction_and_effect":"Agonist: a cryo-EM structure shows one leptin inducing LepR dimerisation through two distinct receptor sites, and a single leptin is sufficient to dimerise two LepR chains and activate STAT3 signalling [PMID:37002197]. Leptin binding to LEPR activates several signalling pathways [DB:UniProt]; Reactome lists LEP:LEPR:JAK2 [DB:Reactome].","molecular_requirements":"Two LepR chains per leptin; the high-affinity site 2 involves the LepR hinge of domains D4-D5 and the lower-affinity site 3 involves the Ig domain D3 [PMID:37002197]. Binding localised to residues 323-640 of LEPR [PMID:9463481]. Coexpressing an inactive LEPR mutant suppressed OB-Rb activity [PMID:9463481].","affinity_potency":[],"species_and_systems":"The cryo-EM full text describes mouse leptin and mouse LepR complexes; signalling used HEK-293T cells [PMID:37002197]. Curators list human for both papers. Structures with both chains are in PDB (e.g. 7Z3Q, 8AVE) [DB:PDB 7Z3Q].","localisation_and_range":"Leptin flagged secreted; LEPR transmembrane [flag]. Circulating hormone acting on LepR in hypothalamic neurons [PMID:37002197].","caveats":"Both papers were read from the abstract only by the curators (cryo-EM paper has full text). Peripheral clearance of leptin can occur by other receptors, see LEP -> LRP2.","key_references":[{"PMID":"37002197","why":"Cryo-EM leptin-LepR complex, asymmetric 1:2 architecture"},{"PMID":"9463481","why":"Maps leptin binding domain to LEPR residues 323-640"}],"covers":["LR001021","LR004439"]},"LR002899":{"pair":"LGALS8 -> ITGA6","headline":"Galectin-8 binds alpha3beta1 integrin; ITGA6 is only inferred from the same paper, which does not name it in the abstract shown.","interaction_type":"functional only","direction_and_effect":"Galectin-8 inhibited adhesion of human 1299 carcinoma cells to plates coated with integrin ligands and induced apoptosis (antagonist of adhesion); effects were not mimicked by galectin-1 or galectin-3, and Mn2+ abolished the inhibition [PMID:10852818].","molecular_requirements":"The identified binder is the alpha3beta1 integrin; alpha6 is not named in the abstract shown [PMID:10852818].","affinity_potency":[],"species_and_systems":"Human 1299 carcinoma cells; alpha3beta1 also from HeLa and human endothelial cells; mouse pair is ortholog-inferred [PMID:10852818].","localisation_and_range":"Galectin-8 is a secreted protein (secreted flag [flag]); endogenous galectin-8 secreted from 1299 cells forms complexes with surface alpha3beta1 integrin [PMID:10852818].","caveats":"ITGA6 is not named in the shown abstract; the human pair is ortholog-inferred rather than directly tested, so support here is indirect. Abstract only; glycan-mediated binding. No affinity reported.","key_references":[{"PMID":"10852818","why":"Galectin-8 binding to alpha3beta1 integrin inhibits adhesion and induces apoptosis"}],"covers":["LR002899","LR006129"]},"LR001030":{"pair":"LPA -> LRP2","headline":"Megalin/gp330 directly binds Lp(a) by surface plasmon resonance; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Purified megalin/gp330 on a sensor chip directly binds Lp(a) in a Ca2+-dependent manner with an affinity similar to that for LDL [PMID:10073957]. Signalling effect is not reported in our evidence.","molecular_requirements":"Binding is Ca2+-dependent [PMID:10073957]. No co-receptor reported.","affinity_potency":[],"species_and_systems":"Human Lp(a) with receptor from a mouse embryonic yolk sac cell line; surface plasmon resonance [PMID:10073957].","localisation_and_range":"LPA is flagged secreted [flag]; megalin is an endocytic receptor.","caveats":"One paper, abstract only; the affinity is not given numerically. One further paper was abstract-insufficient. Species mix of human ligand and mouse receptor.","key_references":[{"PMID":"10073957","why":"SPR shows megalin/gp330 binds Lp(a) Ca2+-dependently"}],"covers":["LR001030"]},"LR009649":{"pair":"NCAM1 -> GFRA1","headline":"NCAM associates with GFRalpha1, enabling high-affinity GDNF signalling; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Association of NCAM with GFRalpha1 downregulates NCAM-mediated adhesion and promotes high-affinity GDNF binding to p140NCAM, activating Fyn and FAK in cells lacking RET [PMID:12837245].","molecular_requirements":"GFRalpha1 acts as co-receptor for GDNF signalling through NCAM; RET is not required for this route [PMID:12837245].","affinity_potency":[],"species_and_systems":"Neural cells (Schwann cells, hippocampal and cortical neurons); species stated as human in curation fields [PMID:12837245].","localisation_and_range":"GFRA1 is a GPI-anchored receptor per the abstract; both partners membrane-bound, so a cis association at the cell surface [PMID:12837245].","caveats":"Abstract only. The evidence is an association with GFRalpha1 rather than a defined ligand-receptor binding assay; the ligand role of NCAM here is partly the reverse of the GDNF-centred model. Reactome lists the complex [DB:Reactome R-HSA-375101].","key_references":[{"PMID":"12837245","why":"NCAM-GFRalpha1 association and RET-independent GDNF signalling"}],"covers":["LR009649"]},"LR002989":{"pair":"NGF -> SORCS2","headline":"Crystal structure shows NGF bound to the SorCS2 beta-propeller in a 2:4 complex; direct binding confirmed by SPR.","interaction_type":"direct binding","direction_and_effect":"NGF dimers bind SorCS2 in a 2:4 (SorCS2:NGF) complex; the curator labels it agonist [PMID:30061605]. UniProt describes a NGFR:SORCS2 heterodimer as receptor for proNGF and proBDNF [DB:UniProt].","molecular_requirements":"Both NGF dimer chains interact exclusively with the top face of a SorCS2 beta-propeller; NGF, proNGF and proBDNF bind at this site [PMID:30061605]. SorCS2 forms cross-braced homodimers; the F630N interface mutation abrogated NGF binding in SPR [PMID:30061605]. UniProt describes the physiological receptor as an NGFR:SORCS2 heterodimer [DB:UniProt].","affinity_potency":[],"species_and_systems":"Soluble SorCS2 ectodomain with NGF; the curator records human ligand and receptor; paper read in full text [PMID:30061605]. The mouse pair is the non-inferred one and the human pair is ortholog-inferred. IntAct SPR record [DB:IntAct].","localisation_and_range":"NGF is annotated secreted [flag]; UniProt places the heterodimer as a receptor for secreted precursors [DB:UniProt].","caveats":"Precursor forms are the physiological ligands according to UniProt [DB:UniProt]; mature NGF binding is shown directly in vitro [PMID:30061605]. Resolution of 3.9 A is modest.","key_references":[{"PMID":"30061605","why":"Crystal structure and SPR of SorCS2-NGF complex"}],"covers":["LR002989","LR006214"]},"LR001102":{"pair":"NLGN1 -> NRXN1","headline":"Well supported trans-synaptic adhesion pair: SPR and affinity chromatography binding plus a functional neurite-outgrowth readout, mostly from abstracts.","interaction_type":"direct binding","direction_and_effect":"Soluble neuroligin-1 binds neurexin-1beta by SPR [PMID:14522992]; neuroligin 1 binds alpha- and beta-neurexins, regulated by splicing, and the beta-only binding variant potently stimulates synapse formation [PMID:16242404]. NLGN1, soluble or membrane-bound, induces neurite outgrowth dependent on NRXN1beta and FGFR1 activation [PMID:22750515].","molecular_requirements":"Splice site B of neuroligin 1 is a master switch for alpha-neurexin binding but leaves beta-neurexin binding largely unaffected; neurexin splice site 4 modulates binding [PMID:16242404]. Neuroligin-1 extracellular domain associates as a dimer, and N-linked glycosylation at position 303 modifies association [PMID:14522992]. Neurite outgrowth also needs FGFR1 [PMID:22750515].","affinity_potency":[],"species_and_systems":"Human recombinant/hippocampal neuron cultures for neurite outgrowth (curator: human) [PMID:22750515]; rat brain proteins for affinity chromatography [PMID:8576240]; other species unspecified. Mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. NLGN1 also appears in BioGRID as a reconstituted complex with NRXN1 [DB:BioGRID].","caveats":"All papers except 8576240 were read as abstracts; the 8576240 quote is a browser read flagged as an unverifiable spot-check pending. No affinity values in our evidence. Results depend on splice isoform.","key_references":[{"PMID":"14522992","why":"SPR of soluble neuroligin-1 with neurexin-1beta"},{"PMID":"16242404","why":"Splice-dependent alpha/beta neurexin binding"},{"PMID":"22750515","why":"Functional NLGN1-NRXN1beta neurite outgrowth"}],"covers":["LR001102","LR004513"]},"LR001111":{"pair":"NMB -> GRPR","headline":"NMB is a lower-affinity, full agonist of GRPR; its preferred receptor is NMBR. Supported by rat and human binding and functional data.","interaction_type":"direct binding","direction_and_effect":"NMB acts as an agonist at GRPR: in rat pancreatic acini NMB and bombesin cross-desensitised each other, indicating a shared receptor [PMID:1720612]. At huGRP-R, bombesin Ki was 1.4 +/- 0.2 nM, with NMB 300-fold weaker [PMID:7838118]. GtoPdb lists NMB-GRPR as full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor reported in our evidence.","affinity_potency":[{"value":"IC50 15-50 nM","assay":"competition binding (curator reader note)","system":"human GRPR, Balb 3T3 and HuTu-80 cells","cite":"PMID:21729729"},{"value":"EC50 2 nM","assay":"amylase secretion","system":"rat pancreatic acini","cite":"PMID:1720612"},{"value":"EC50 141 nM","assay":"inositol phosphate production","system":"rat pancreatic acini","cite":"PMID:1720612"},{"value":"pKi 6.36-8.13","assay":"GtoPdb pKi range","system":"curated records","cite":"PMID:7838118"},{"value":"pIC50 7.42-7.52","assay":"GtoPdb pIC50 range","system":"curated records","cite":"PMID:21729729"}],"species_and_systems":"Rat pancreatic acini [PMID:1720612]; human receptor in cells [PMID:7838118][PMID:21729729]. Mouse pair is ortholog-projected, not tested.","localisation_and_range":"NMB is flagged secreted and GRPR transmembrane [flag]; paracrine peptide signalling to a GPCR.","caveats":"NMB prefers NMBR (0.052-0.054 nM, >650-fold higher than for hGRP receptors) [PMID:21729729]; the GRPR interaction is cross-reactive. Rat and human data differ markedly for GRP receptors [PMID:21729729]. The rat study's receptor is not named GRPR in the abstract. Other papers were abstract-insufficient.","key_references":[{"PMID":"21729729","why":"Human GRPR/NMBR competition binding, full text"},{"PMID":"7838118","why":"Cloned human GRPR agonist affinities"},{"PMID":"1720612","why":"Rat acinar shared receptor, EC50s"}],"covers":["LR001111","LR004522"]},"LR001120":{"pair":"NODAL -> ACVR2B","headline":"ACVR2B is a Nodal type II receptor: binding of Xnr1 plus reconstitution, and frog-assay dominant-negative data.","interaction_type":"direct binding","direction_and_effect":"ALK7 and ActRIIB collaborate to confer responsiveness to Xnr1 and Nodal [PMID:11485994]. ActRIIA or ActRIIB can serve as type II receptor with ALK4 in frog animal caps; effect is agonist [PMID:11952836].","molecular_requirements":"ActRIIB needs a type I partner (ALK7, or ALK4 with Cripto); Cripto binds Nodal-related Xnr1 and ALK7, and enhances responses [PMID:11485994]. ACVR2A can substitute for ACVR2B [PMID:11952836]. BioGRID lists a reconstituted complex [DB:BioGRID, PMID:28126904].","affinity_potency":[],"species_and_systems":"Mouse receptors and Nodal, and Xenopus Nodal-related 1 (Xnr1), in reconstitution; frog animal caps. Both papers abstract only. The mouse pair is not ortholog-inferred; the human pair is.","localisation_and_range":"Nodal flagged secreted, ACVR2B transmembrane [flag].","caveats":"The binding statement ('Both receptors can independently bind Xnr1') is for Xenopus Xnr1, not Nodal itself [PMID:11485994]. No affinity reported. The frog paper is dominant-negative evidence only [PMID:11952836].","key_references":[{"PMID":"11485994","why":"ALK7 and ActRIIB bind Xnr1 independently; reconstitution with Nodal"},{"PMID":"11952836","why":"ActRIIA/ActRIIB as Nodal type II receptors"}],"covers":["LR001120","LR004531"]},"LR008488":{"pair":"NOG -> GDF5","headline":"Noggin interacts with GDF5 and inhibits chondrogenic differentiation; supported by SPR and UniProt only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says Noggin inhibits chondrocyte differentiation through its interaction with GDF5 [DB:UniProt, PMID:21976273]; interaction is annotated Inhibitory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists surface plasmon resonance [DB:IntAct, PMID:16127465]; species not reported.","localisation_and_range":"GDF5 is flagged both secreted and transmembrane [flag], which is ambiguous.","caveats":"No curated paper (two rated different entity). The UniProt text cites other papers, so this is database assertion plus an SPR record.","key_references":[{"PMID":"16127465","why":"IntAct SPR record for GDF5-NOG (database only)"}],"covers":["LR008488"]},"LR002998":{"pair":"NPTX1 -> GRIA4","headline":"NPTX1 is reported to bind the GluR4 N-terminal domain in one coculture study; thin evidence.","interaction_type":"direct binding","direction_and_effect":"NP1 and NPR secreted from presynaptic neurons bind the GluR4 NTD and are required for GluR4 recruitment to synapses [PMID:17610819].","molecular_requirements":"GluR4 NTD is necessary and sufficient for recruitment; NP1 and NPR are both required [PMID:17610819]. NPTX1 may act with NPTXR.","affinity_potency":[],"species_and_systems":"Artificial-synapse coculture with RNAi and knockout; species not stated in dossier [PMID:17610819]. Both pairs are ortholog-inferred.","localisation_and_range":"NPTX1 is annotated secreted [flag]; the paper describes trans-synaptic action [PMID:17610819].","caveats":"One paper, abstract only; no database records. NP1 and NPR effects are not separated in the abstract. Not a classical signalling receptor interaction, rather a synaptic recruitment factor.","key_references":[{"PMID":"17610819","why":"NP1/NPR bind GluR4 NTD for synaptic recruitment"}],"covers":["LR002998","LR006222"]},"LR003001":{"pair":"NPY -> GPR83","headline":"Rat-only evidence that NPY binds and activates rat GPR83; the human and mouse pairs are projected from it.","interaction_type":"direct binding","direction_and_effect":"NPY displaced 125I-PYY(3-36) from rat GIR (Gpr83) and activated 35S-GTPgammaS binding, acting as an agonist with a Y2-like profile [PMID:17240481].","molecular_requirements":"Single receptor; no co-receptor reported in our evidence.","affinity_potency":[{"value":"Ki 95 nM","assay":"BIIE0246 displacement of 125I-PYY(3-36) (Y2 antagonist, not NPY itself)","system":"rat GIR-transfected cells","cite":"PMID:17240481"}],"species_and_systems":"Rat ligand and rat receptor in transfected cells [PMID:17240481]. Human and mouse interactions are ortholog-inferred, with no human experiment in our evidence.","localisation_and_range":"NPY is flagged secreted [flag]; GPR83 localisation is not reported in our evidence.","caveats":"One paper, read as abstract only; NPY is described as high-affinity (low nanomolar) but no NPY value is given. The 95 nM is for the antagonist BIIE0246. Human relevance rests on ortholog projection. No database support.","key_references":[{"PMID":"17240481","why":"NPY-family peptides bind and activate rat GIR"}],"covers":["LR003001","LR006225"]},"LR008596":{"pair":"NRG1 -> ERBB2:ERBB4","headline":"NRG1 binds ERBB4 directly; ERBB2 joins by heterodimerisation, so the complex is supported mainly through ERBB4.","interaction_type":"direct binding","direction_and_effect":"Heregulin acts as an agonist: it binds ERBB4 and activates ERBB4 and ERBB2 via transphosphorylation or heterodimerisation [PMID:8062828]. The EGF-like domain is sufficient for activation [PMID:8062828]; residues 177-226 are sufficient for binding and receptor phosphorylation [PMID:7721889].","molecular_requirements":"Direct binding evidence is for ERBB4 [PMID:9565587] [PMID:7721889]; ERBB2 is engaged through heterodimerisation, not direct binding, per the abstracts [PMID:8062828]. A soluble ErbB2/4 heterodimer bound all eleven ligands tested with moderate to very high affinity, and ErbB2 enhanced ligand binding to ErbB4 [PMID:10214951].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; phage display with receptor-IgG fusions, soluble receptors, synthetic peptides, breast tumour cell lines [PMID:9565587] [PMID:10214951] [PMID:1350381].","localisation_and_range":"NRG1 is flagged secreted and transmembrane [flag], so both paracrine and juxtacrine action are possible; not tested in these papers.","caveats":"All five papers were read as abstracts only. The 1992 discovery paper shows ERBB2 phosphorylation and a Kd (105 +/- 15 picomolar) for a cell line expressing p185erbB2, but does not name ErbB4 [PMID:1350381]. Complex-level binding rests on one soluble-receptor study; no affinity for the ERBB2:ERBB4 pair is quoted in our evidence.","key_references":[{"PMID":"8062828","why":"HRG binds ErbB4 and activates ErbB2 by heterodimerisation"},{"PMID":"10214951","why":"Soluble ErbB2/4 heterodimer binds ligands incl. heregulin"},{"PMID":"9565587","why":"Phage-displayed HRGbeta EGF domain binds ErbB4-IgG"}],"covers":["LR008596"]},"LR003010":{"pair":"NRG3 -> ERBB3","headline":"NRG3 activates ERBB3 only together with ERBB2, from one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"NRG-3 activated erbB3 when co-expressed with erbB2 in cells, an agonist effect [PMID:9772300].","molecular_requirements":"ERBB3 is not shown to respond alone; activation required erbB2 co-expression [PMID:9772300].","affinity_potency":[],"species_and_systems":"Human breast cancer cells and transfected 32D cells [PMID:9772300]. Mouse pair is projected from human.","localisation_and_range":"Annotated secreted and transmembrane [flag].","caveats":"One paper, abstract only; activation not binding; no affinity. Direct NRG3-ERBB3 binding is not shown.","key_references":[{"PMID":"9772300","why":"erbB2 and erbB3 activated together by NRG-3"}],"covers":["LR003010","LR006234"]},"LR008929":{"pair":"NTN3 -> CDON","headline":"Database-asserted only: Reactome complex and a UniProt by-similarity note; no verified paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond database records.","molecular_requirements":"Reactome lists a complex of CDO, BOC, Neogenin and Netrin-3, which includes this receptor with other subunits [DB:Reactome].","affinity_potency":[],"species_and_systems":"Not reported in our evidence. UniProt gives \"Interacts with NTN3 (By similarity)\" [DB:UniProt].","localisation_and_range":"Not reported in our evidence.","caveats":"The one paper judged was abstract_insufficient. Support rests entirely on Reactome and a by-similarity UniProt line.","key_references":[],"covers":["LR008929"]},"LR001201":{"pair":"PDYN -> OPRD1","headline":"Dynorphin A peptides bind the cloned delta receptor, with kappa preference; evidence is from a 1995 binding paper.","interaction_type":"direct binding","direction_and_effect":"Dynorphin A peptides prefer kappa but also bind the cloned delta and mu receptors [PMID:8624732]. GtoPdb records an agonist (full agonist) interaction [DB:GtoPdb].","molecular_requirements":"Peptide-derived ligands (dynorphin A fragments from prodynorphin) were tested [PMID:8624732].","affinity_potency":[],"species_and_systems":"Cloned human receptors transiently expressed in COS-1 cells; abstract only [PMID:8624732].","localisation_and_range":"PDYN flagged secreted; OPRD1 transmembrane [flag].","caveats":"Delta is a secondary target; no numeric affinity in our evidence for delta. GtoPdb lists pKi units but no values in our dossier. Mouse and human pairs are ortholog-inferred.","key_references":[{"PMID":"8624732","why":"Cloned opioid receptor binding of prodynorphin peptides, incl. delta"}],"covers":["LR001201","LR004610"]},"LR003100":{"pair":"PIANP -> PILRA","headline":"PIANP binds PILRA-Ig on transfected cells and stimulates PILRA reporter cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PILR-alpha-Ig fusion protein bound PANP-transfected cells, and the transfectants stimulated PILR-alpha reporter cells [PMID:21241660]. PILR-alpha is described as an immune inhibitory receptor with an ITIM [PMID:21241660]. Reactome also lists PILRA binding PIANP [DB:Reactome R-HSA-8862090].","molecular_requirements":"Specific O-glycan structures on PANP are required for PILR recognition [PMID:21241660]. Complex partners or chains: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the cells and constructs: not reported in our evidence (abstract only) [PMID:21241660]. PANP transcription was mainly in neural tissues [PMID:21241660]. IntAct lists a FACS-based record [DB:IntAct Q9UKJ1-Q8IYJ0].","localisation_and_range":"PIANP is annotated as not secreted, so likely membrane-bound and juxtacrine [flag]; PILRA carries secreted, receptor and transmembrane flags [flag].","caveats":"Only one paper, read as abstract; no affinity. Reactome record groups PILRA with other ligands (COLLEC12 trimer, NPDC1, CLEC4G) [DB:Reactome R-HSA-8862090].","key_references":[{"PMID":"21241660","why":"PANP as O-glycosylated PILR-alpha ligand: Ig-binding and reporter assays"}],"covers":["LR003100","LR006322"]},"LR009685":{"pair":"PSAP -> CD1B","headline":"Saposin C directly interacts with CD1b to enable lipid presentation; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Coprecipitation demonstrated direct molecular interaction between saposin C and CD1b, and saposin C is required for lipid presentation by human CD1b [PMID:14716313].","molecular_requirements":"The saposin C domain of PSAP is the partner, not the full precursor [PMID:14716313].","affinity_potency":[],"species_and_systems":"Human fibroblasts [PMID:14716313].","localisation_and_range":"PSAP is flagged secreted [flag]; CD1b is an antigen-presenting molecule, so this is a lipid-loading relation rather than signalling.","caveats":"One abstract-only paper; affinity not reported in our evidence. CD1b has no receptor flag in the dossier, and this is not classic ligand-receptor signalling.","key_references":[{"PMID":"14716313","why":"Saposin C coprecipitates with CD1b and is required for lipid presentation."}],"covers":["LR009685"]},"LR007939":{"pair":"PSPN -> GFRA4:RET","headline":"Persephin signals through a GFRA4:RET complex per Reactome and UniProt; no curator-verified paper on the complex row.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records PSPN binding the RET:GFRA4 complex [DB:Reactome], and UniProt says PSPN acts through GFRA4 leading to RET autophosphorylation and activation [DB:UniProt].","molecular_requirements":"Both GFRA4 and RET are members of the complex [flag]; UniProt names GFRA4 as coreceptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex for PSPN-GFRA4 [DB:BioGRID]; species and system not reported in our evidence.","localisation_and_range":"Ligand flagged secreted; complex flagged transmembrane [flag].","caveats":"No papers were verified for the complex row itself (abstract_insufficient or different_entity); support is database records. Related paper evidence is in the PSPN -> GFRA4 pair.","key_references":[],"covers":["LR007939"]},"LR001300":{"pair":"RLN3 -> RXFP1","headline":"Relaxin-3 activates RXFP1 (LGR7) in vitro and in vivo, supported by two abstract-read papers and database records.","interaction_type":"direct binding","direction_and_effect":"Synthetic human relaxin-3 showed high activity at LGR7 from various species and activated native LGR7 in rat ventricular fibroblasts, increasing MMP-2 expression, and after intraventricular infusion in rats stimulated water drinking [PMID:16411781]. It activated LGR7 via cAMP in chimeric-receptor assays as a full agonist [PMID:12506116]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Activation involves binding to both the ectodomain and exoloop 2 of LGR7 [PMID:12506116]. Other subunit requirements are not reported in our evidence.","affinity_potency":[{"value":"pKi 7.5 to 8.0","assay":"GtoPdb affinity range (pKi)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"Curated as human ligand and receptor; experiments also used rat cells and rat in vivo [PMID:16411781]. The mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag]; paracrine or endocrine signalling to a membrane receptor.","caveats":"Both papers read as abstracts only. Relaxin-3's highest activity was at its own receptor GPCR135, so RXFP1 is a secondary target [PMID:16411781]. BioGRID lists a protein-peptide record [DB:BioGRID]. Two papers are still pending.","key_references":[{"PMID":"16411781","why":"Relaxin-3 activates native LGR7 in rat fibroblasts and in vivo"},{"PMID":"12506116","why":"H3 relaxin activates LGR7; ectodomain plus exoloop 2"}],"covers":["LR001300","LR004698"]},"LR004699":{"pair":"RLN3 -> RXFP2","headline":"Relaxin-3 shows only variable activity at RXFP2 in one abstract-read paper; weak support.","interaction_type":"functional only","direction_and_effect":"Synthetic human relaxin-3 showed variable activity on the INSL3 receptor (LGR8/RXFP2) [PMID:16411781]. GtoPdb lists a full agonist, with no affinity value given [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor as curated; the mouse pair is projected from human evidence (ortholog inferred). Assay system details are not reported beyond the abstract.","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag].","caveats":"Single paper read as abstract only; activity was weaker and less consistent than at RXFP1 or GPCR135 [PMID:16411781]. Direct binding to RXFP2 was not shown in the text we have.","key_references":[{"PMID":"16411781","why":"Reports variable relaxin-3 activity at LGR8/RXFP2"}],"covers":["LR001301","LR004699"]},"LR007399":{"pair":"SEMA3A -> NRP1:PLXNA4","headline":"SEMA3A acting through an NRP1:PLXNA4 receptor complex, supported mainly by mouse genetics and database complex records; no direct binding of the full complex shown.","interaction_type":"functional only","direction_and_effect":"Sema3A-insensitive sensory and sympathetic neurons in Plexin-A3/A4 double-mutant mice identify these plexins as signalling co-receptors of the Neuropilin-1 complex; Neuropilin-1 signalling is mediated principally by Plexin-A4 [PMID:15721238]. A third paper supports SEMA3A signalling through NRP1 in GnRH neuron migration [PMID:21059704].","molecular_requirements":"Complex of NRP1 and PLXNA4 [flag]. Reactome describes Sema3A binding Nrp-1 bound to PlexinA [DB:Reactome]; BioGRID lists a reconstituted NRP1-SEMA3A complex [DB:BioGRID]. A screen reports Sema3A-PlxnA4 binding that may occur without Nrp1, so NRP1 may not be obligatory [PMID:26633812].","affinity_potency":[],"species_and_systems":"Evidence is from mouse (Plexin-A3/A4 double mutant neurons, GnRH neuron models) [PMID:15721238][PMID:21059704]; the screen used purified ectodomains and is labelled human in the dossier [PMID:26633812].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors. The receptor complex is membrane-bound [flag].","caveats":"Both key papers were read as abstracts only. The holoreceptor architecture is background in [PMID:26633812], which instead suggests Nrp1 may be dispensable for direct Sema3A-PlxnA4 binding. [PMID:21059704] does not name PLXNA4 in its visible abstract. No affinity data in our evidence.","key_references":[{"PMID":"15721238","why":"Plexin-A3/A4 double mutant: Plexin-A4 mainly mediates Sema3A signalling via NRP1"},{"PMID":"26633812","why":"Screen suggesting Sema3A-PlxnA4 binding may not need Nrp1"},{"PMID":"21059704","why":"SEMA3A signalling through NRP1 in GnRH neuron migration (weak for PLXNA4)"}],"covers":["LR007399"]},"LR004789":{"pair":"SLIT2 -> GPC1","headline":"SLIT2 binds glypican-1 with Kd 80-110 nM; heparan sulfate dependent, supported by two papers and BioGRID/Reactome.","interaction_type":"direct binding","direction_and_effect":"Glypican-1 is a Slit2 ligand-binding partner; Slit proteins were isolated from rat brain on a glypican-Fc matrix [PMID:10364234]. Binding was saturable and reversible [PMID:11375980]. Functional effect on glypican-1-bearing cells is not reported in our evidence.","molecular_requirements":"Binding needs glypican heparan sulfate chains [PMID:10364234]; heparin, heparitinase or chlorate cut binding 80-90% [PMID:11375980]. The glypican core protein binds Slit about an order of magnitude more weakly [PMID:11375980]. The C-terminal Slit2 fragment binds; the larger N-terminal segment binds little [PMID:11375980].","affinity_potency":[{"value":"Kd 80-110 nM","assay":"ELISA, glypican-Fc binding to Slit-2 (full-length and C-terminal fragment)","system":"recombinant human Slit-2, glypican-Fc","cite":"PMID:11375980"}],"species_and_systems":"Rat brain extract with human glypican-Fc [PMID:10364234]; recombinant human Slit-2 and 293-cell co-transfection immunoprecipitation [PMID:11375980]. Mouse pair is ortholog-inferred.","localisation_and_range":"Glypican-1 is a GPI-anchored membrane proteoglycan; the C-terminal Slit2 portion is released from the cell membrane [PMID:11375980]. Colocalisation in embryonic and adult CNS [PMID:11375980]. Interactions also in BioGRID and Reactome [DB:BioGRID][DB:Reactome].","caveats":"Both papers read as abstracts only. Receptor-versus-matrix-binding role of glypican is not resolved in our evidence. One pending row not shown.","key_references":[{"PMID":"11375980","why":"Kd 80-110 nM, fragment and HS dependence"},{"PMID":"10364234","why":"Slit1/2 isolated on glypican-1-Fc"}],"covers":["LR001394","LR004789"]},"LR001999":{"pair":"SNCA -> LAG3","headline":"LAG3 binds alpha-synuclein pre-formed fibrils with Kd 77 nM; monomer binds minimally; supported by BioGRID.","interaction_type":"direct binding","direction_and_effect":"LAG3 binds alpha-syn PFF; binding initiated PFF endocytosis, transmission and toxicity, and loss of LAG3 delayed PFF-induced dopamine neuron loss in vivo [PMID:27708076].","molecular_requirements":"Fibrillar alpha-syn is the binding form; the monomer showed minimal binding [PMID:27708076]. Other co-receptors are not reported in this abstract.","affinity_potency":[{"value":"Kd 77 nM","assay":"biochemical binding assay (recombinant proteins), per curator","system":"alpha-syn PFF with LAG3","cite":"PMID:27708076"}],"species_and_systems":"Both human and mouse pairs are curated directly; experimental species are not stated in the abstract. Recombinant proteins, cells and in vivo knockout [PMID:27708076].","localisation_and_range":"SNCA is flagged secreted; LAG3 is flagged receptor and transmembrane, so it acts as a membrane receptor [flag]. Cell-to-cell spread is the proposed route [PMID:27708076].","caveats":"Paper read as abstract only. BioGRID lists an affinity capture-Western record from a different paper (34309222) [DB:BioGRID]. Only fibrillar, not monomeric, alpha-syn binds well.","key_references":[{"PMID":"27708076","why":"LAG3 binds alpha-syn PFF with Kd 77 nM and mediates transmission"}],"covers":["LR001999","LR005327"]},"LR002002":{"pair":"SOSTDC1 -> LRP6","headline":"Wise/SOSTDC1 physically binds LRP6 and competes with Wnt8; three papers, all abstract-level, with a context-dependent effect.","interaction_type":"direct binding","direction_and_effect":"Wise interacts physically with LRP6 and competes with Wnt8 for binding; it activates Wnt signalling in Xenopus animal caps but antagonises Wnt8-induced secondary axis, so effect is context-dependent [PMID:12900447]. In human-origin work Wise blocks Wnt1 activity via LRP6 [PMID:19553665]. In mouse tooth it inhibits Lrp5/6-dependent Wnt signalling [PMID:20724449].","molecular_requirements":"Wise binds LRP6 through one of three cystine-knot loops; a deletion lacking that loop still binds BMP4, and BMP4 does not interfere with Wise-LRP6 binding. Extra LRP6 prevents Wise inhibiting BMP4 [PMID:19553665].","affinity_potency":[],"species_and_systems":"Xenopus [PMID:12900447]; human proteins [PMID:19553665]; mouse tooth in vivo [PMID:20724449]. Mouse pair ortholog-inferred.","localisation_and_range":"Wise is secreted; acts on the surface co-receptor LRP6 [flag] [PMID:19553665] (cell-surface heparan sulfate association noted).","caveats":"All abstracts only. Activating versus inhibiting outcome depends on context. No affinity values. No database records.","key_references":[{"PMID":"12900447","why":"Wise binds LRP6, competes with Wnt8; dual activity"},{"PMID":"19553665","why":"Wise binds LRP6 via a cystine-knot loop, separate from BMP4"},{"PMID":"20724449","why":"Mouse tooth genetics, Lrp5/6 dependence"}],"covers":["LR002002","LR005330"]},"LR004798":{"pair":"SPON2 -> ITGB2","headline":"Mindin (SPON2) binds beta2 integrin Mac-1 on macrophages; supported by two papers read as abstracts, one with full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"Mindin serves as a ligand for integrin Mac-1 (CD11b/CD18): 131I-labelled mindin binds Mac-1 and mindin promotes macrophage phagocytosis via Syk activation and NF-kB p65 translocation [PMID:30869196]. Neutrophil adhesion to mindin is blocked by anti-integrin alpha4, alpha(M) and beta2 antibodies [PMID:16105980].","molecular_requirements":"The F-spondin fragment of mindin binds the alphaM-I domain of Mac-1 [PMID:30869196]. ITGB2 pairs with alphaM (CD11b) here, so the receptor is the alphaM/beta2 heterodimer; beta2 alone is not shown to suffice. Anti-alpha4 also blocked neutrophil adhesion [PMID:16105980].","affinity_potency":[],"species_and_systems":"Mindin-null mice impaired in neutrophil and macrophage recruitment in 4 inflammation models; HEK-293 cells transfected with integrin cDNAs bound mindin matrix more [PMID:16105980]. Mac-1 work used mindin-deficient mice, macrophages, RAW264.7 cells and mouse recombinant mindin in HEK293T cells expressing mouse CD11b/CD18 [PMID:30869196]. Dossier lists the experiment species as human for PMID:16105980 but describes mouse models.","localisation_and_range":"SPON2 is flagged secreted and ITGB2 not secreted [flag]; the papers describe mindin as an extracellular matrix protein, immobilised matrix in the adhesion assays [PMID:16105980].","caveats":"Both papers were read as abstracts (the second with full-text excerpts); PMID:16105980 does not name the beta2 partner in the binding claim itself. Human and mouse interactions are both ortholog-inferred.","key_references":[{"PMID":"30869196","why":"Radiolabelled mindin binds Mac-1; FS fragment binds alphaM-I domain"},{"PMID":"16105980","why":"Neutrophil adhesion to mindin blocked by anti-beta2/alphaM antibodies; recruitment in vivo"}],"covers":["LR001403","LR004798"]},"LR008695":{"pair":"TFPI -> F3","headline":"No verified paper; only database records describing TFPI-beta binding to the TF:FVIIa:FXa complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"Reactome lists TFPIbeta binding TF:FVIIa:FXa, i.e. the ternary complex rather than F3 alone [DB:Reactome]. PDB 9P0X is a nanodisc TF/FVIIa/XK1 structure with 10H10 Fab [DB:PDB 9P0X].","affinity_potency":[],"species_and_systems":"Species: the PDB entry is described as human; no experimental paper is verified for this pair.","localisation_and_range":"TFPI is annotated secreted and F3 as a receptor [flag].","caveats":"Only one review-only paper was found; the pair rests on databases alone. The Reactome record involves FVIIa and FXa, so a direct TFPI-F3 binary interaction is not shown.","key_references":[],"covers":["LR008695"]},"LR006589":{"pair":"THBS4 -> ITGB1","headline":"THBS4 interacts with ITGB1 to drive HCC proliferation through FAK/PI3K/AKT; co-IP evidence.","interaction_type":"direct binding","direction_and_effect":"THBS4 as an oncogene interacts with integrinbeta1 to regulate HCC development via FAK/PI3K/AKT [PMID:32567740]. Agonist-like.","molecular_requirements":"Also binds ITGB5 and ITGA5 in the same study [PMID:32567740].","affinity_potency":[],"species_and_systems":"Human HCC cell lines and tissues, in vitro and in vivo [PMID:32567740].","localisation_and_range":"THBS4 flagged secreted [flag].","caveats":"Abstract-level read; IntAct co-IP record [DB:IntAct]. Mouse pair ortholog-inferred.","key_references":[{"PMID":"32567740","why":"THBS4 interacts with ITGB1 in HCC"}],"covers":["LR003388","LR006589"]},"LR006598":{"pair":"THY1 -> ITGB2","headline":"Thy-1 binds beta2 integrins (Mac-1, alphaX-beta2) in human cell and protein assays; evidence is complex-level.","interaction_type":"direct binding","direction_and_effect":"Thy-1/Mac-1 mediates leukocyte adhesion and transendothelial migration [PMID:15004192].","molecular_requirements":"ITGB2 is the shared beta chain; the Thy-1 binding shown is for Mac-1 and the alphaX I-domain, not the beta2 chain alone [PMID:15004192][PMID:15850796].","affinity_potency":[],"species_and_systems":"Human: monocytes, PMNs, endothelial cells, purified protein [PMID:15004192]; recombinant I-domain [PMID:15850796].","localisation_and_range":"Membrane-bound; contact-dependent.","caveats":"Both abstract only; chain-level row inherits complex evidence; mouse pair is ortholog-inferred.","key_references":[{"PMID":"15004192","why":"Thy-1/Mac-1 binding"},{"PMID":"15850796","why":"alphaX I-domain binds Thy-1"}],"covers":["LR003397","LR006598"]},"LR002020":{"pair":"TIGIT -> PVR","headline":"TIGIT binds PVR (CD155) with high affinity and acts as an inhibitory receptor; two abstract-only papers plus structure.","interaction_type":"direct binding","direction_and_effect":"TIGIT-Fc inhibited T cell activation in vitro in a dendritic-cell dependent way; PVR binding on human DCs raised IL-10 and lowered IL-12p40 [PMID:19011627]. In NK cells TIGIT inhibits cytotoxicity directly via its ITIM [PMID:19815499].","molecular_requirements":"TIGIT contains an ITIM [PMID:19011627]. No additional subunit requirement reported.","affinity_potency":[],"species_and_systems":"Human DCs and T cells with TIGIT-Fc; DTH in wild-type and IL-10-deficient mice [PMID:19011627]; human NK cells [PMID:19815499]. PDB 3UDW [DB:PDB 3UDW].","localisation_and_range":"TIGIT is membrane-bound; PVR carries a secreted flag [flag] but papers describe cell-surface PVR on DCs and target cells [PMID:19011627].","caveats":"'High affinity' is stated without a number [PMID:19011627]. Both papers abstract only. TIGIT knockdown in human memory T cells had no effect [PMID:19011627].","key_references":[{"PMID":"19011627","why":"TIGIT-PVR high-affinity binding and DC-mediated suppression"},{"PMID":"19815499","why":"Direct NK inhibition via TIGIT"}],"covers":["LR002020","LR005348"]},"LR004888":{"pair":"TNFSF12 -> TNFRSF12A","headline":"TWEAK binds Fn14 (TNFRSF12A) with nanomolar affinity, shown by five assays; well supported.","interaction_type":"direct binding","direction_and_effect":"Five different assays demonstrate TWEAK-TweakR binding [PMID:11728344]. Cross-linking TweakR induces HUVEC growth, and soluble TweakR inhibits endothelial migration and corneal angiogenesis [PMID:11728344]. TWEAK activates NF-kappaB in mouse NIH 3T3 cells [PMID:12529173]. Effect: agonist.","molecular_requirements":"The TweakR cytoplasmic domain binds TRAFs 1, 2 and 3; TRAF 1, 2, 3 and 5 bind the murine Fn14 tail and an intact TRAF site is needed for NF-kappaB activation [PMID:11728344][PMID:12529173].","affinity_potency":[{"value":"Kd 2.3 +/- 0.1 nM","assay":"binding affinity from five assays (types not stated in abstract)","system":"human TWEAK and TweakR","cite":"PMID:11728344"}],"species_and_systems":"Human receptor cloned from HUVEC [PMID:11728344]; human TWEAK extracellular domain also binds murine Fn14, tested in NIH 3T3 cells [PMID:12529173]. Databases: IntAct ELISA [DB:IntAct], Reactome [DB:Reactome], GtoPdb without type or affinity [DB:GtoPdb].","localisation_and_range":"TWEAK is flagged secreted and transmembrane; Fn14 is a type I transmembrane protein [PMID:12529173].","caveats":"Both papers were read as abstracts.","key_references":[{"PMID":"11728344","why":"Cloning of TweakR and Kd of TWEAK binding"},{"PMID":"12529173","why":"Human TWEAK binds mouse Fn14; TRAF and NF-kappaB signalling"}],"covers":["LR001497","LR004888"]},"LR009496":{"pair":"TNFSF13 -> TNFRSF11B","headline":"No curated paper evidence; support rests on one BioGRID reconstituted-complex record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond a BioGRID reconstituted-complex record [DB:BioGRID].","localisation_and_range":"Ligand flagged secreted; receptor not flagged as receptor or transmembrane [flag].","caveats":"Four papers were judged abstract_insufficient and none confirmed. The only record is BioGRID, citing PMID 10706119 [DB:BioGRID]. Treat as unverified.","key_references":[],"covers":["LR009496"]},"LR004897":{"pair":"TNFSF14 -> TNFRSF14","headline":"LIGHT-HVEM is well supported by several papers and structures; activating, with a mast-cell costimulation example.","interaction_type":"direct binding","direction_and_effect":"HVEM binds LIGHT, and HSV1 gD inhibits the HVEM-LIGHT interaction [PMID:9462508]. In human mast cells, TNFSF14 with anti-IgE enhanced LAMP-1 and IL-8 and TNF-alpha production, with no response to TNFSF14 alone [PMID:27982078].","molecular_requirements":"TNFRSF14 engagement activated mast cells only alongside Fc\u03b5RI aggregation [PMID:27982078]. LIGHT also engages LTBR [PMID:9462508].","affinity_potency":[],"species_and_systems":"Human cells and recombinant proteins; LAD2 and cultured peripheral blood mast cells [PMID:27982078]; immunoprecipitation cross-reactivity with mouse LIGHT [PMID:11390428].","localisation_and_range":"LIGHT flagged secreted and transmembrane; HVEM transmembrane, not secreted [flag]; described as a type II transmembrane protein [PMID:9462508].","caveats":"Several papers abstract only. One shows binding only indirectly, through competition by decoy TR6-Fc [PMID:11390428]. PDB structures exist [DB:PDB 4RSU].","key_references":[{"PMID":"9462508","why":"Identification of HVEM as LIGHT receptor"},{"PMID":"11390428","why":"TR6-Fc competes with HVEM for LIGHT"},{"PMID":"27982078","why":"Mast-cell costimulation via TNFRSF14"}],"covers":["LR001507","LR004897"]},"LR007993":{"pair":"TSLP -> CRLF2:IL7R","headline":"TSLP signals through a CRLF2:IL7R heterodimer; cells with both subunits proliferate and phosphorylate Stat3 and Stat5.","interaction_type":"functional only","direction_and_effect":"Agonist: cells transfected with both receptor subunits proliferated in response to purified, recombinant human TSLP, with induced phosphorylation of Stat3 and Stat5 [PMID:11418668]. GtoPdb lists agonist records [DB:GtoPdb].","molecular_requirements":"Both TSLPR (CRLF2) and IL-7R alpha-chain are needed in the reported assay; the heterodimeric complex is proposed [PMID:11418668]. Structures with both chains exist [DB:PDB 5J11].","affinity_potency":[],"species_and_systems":"Transfected cells with recombinant human TSLP; human monocytes and dendritic cells express both subunits [PMID:11418668].","localisation_and_range":"TSLP flagged secreted and soluble; complex flagged transmembrane [flag].","caveats":"Abstract read only; direct binding affinity is not reported in our evidence.","key_references":[{"PMID":"11418668","why":"TSLP signals via TSLPR + IL-7Ralpha, Stat3/Stat5 phosphorylation"}],"covers":["LR007993"]},"LR008677":{"pair":"VTN -> KDR","headline":"Vitronectin and KDR were co-detected and predicted to interact in mouse embryonic brain; no binding assay.","interaction_type":"functional only","direction_and_effect":"A mouse E14.5 brain study predicted vitronectin signalling from mural cells to KDR on endothelial cells from transcriptomes and reported overlapping VTN and KDR immunofluorescence, which the authors call confirmation of the interaction [PMID:31677479]. The effect is not reported in this paper; the Inhibitory label comes from the dossier metadata.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse embryonic day 14.5 brain, in vivo tissue sections; the pair is human [PMID:31677479].","localisation_and_range":"Vitronectin is flagged as secreted [flag]; the paper places expression in mural cells and KDR in endothelial cells [PMID:31677479].","caveats":"Evidence is co-localisation and expression, not binding or signalling. The authors state the significance is unknown and note the prediction relies on a curated list of interactions. Reported inhibition by glycated VTN in HUVEC is background from other work. One further paper was review only.","key_references":[{"PMID":"31677479","why":"Transcriptomic prediction and immunofluorescence overlap of VTN and KDR in E14.5 mouse brain"}],"covers":["LR008677"]},"LR010999":{"pair":"WNT10B -> FZD8:LRP5","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Two curation rows are still pending; no paper has been judged.","key_references":[],"covers":["LR010999"]},"LR004969":{"pair":"WNT2 -> FZD1","headline":"Fzd1 cooperates weakly with Wnt2 in TCF reporter assays; binding of Wnt2 was not shown.","interaction_type":"functional only","direction_and_effect":"Human Fzd1 enhanced TCF-dependent transcription with Wnt-3a, -3, -1 and to a lesser extent Wnt-2 in a paracrine assay [PMID:10557084]. UniProt states FZD1 is activated by WNT3A, WNT3, WNT1 and to a lesser extent WNT2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Hfz1 (human) in a cell reporter assay; Wnt species and cell line not reported in our evidence; abstract only. Mouse pair ortholog-inferred.","localisation_and_range":"Wnt2 flagged secreted [flag]; paracrine mode was tested [PMID:10557084].","caveats":"Wnt-2 was a weaker partner. Co-IP was shown only for Wnt-3a and Wnt-5a, and the authors say signalling is not set by binding alone [PMID:10557084]. No affinity.","key_references":[{"PMID":"10557084","why":"Hfz1 enhances TCF signalling with Wnt-3a, -3, -1, weakly Wnt-2"}],"covers":["LR001580","LR004969"]},"LR006679":{"pair":"WNT2B -> FZD3","headline":"Direct binding evidence: WNT2B transfers to purified FZD3-CRD from carrier proteins (preprint, human proteins).","interaction_type":"direct binding","direction_and_effect":"WNT2B was rapidly transferred from SFRP2 and GPC4 to FZD3-CRD; the paper labels WNT2B non-canonical, and FZD3 rescue of FZD-knockout cells supports functional specificity [PMID:39229119].","molecular_requirements":"The cysteine-rich domain of FZD3 was sufficient for transfer; FZD3 or FZD6 (not FZD7) rescued FZD-knockout cells [PMID:39229119]. Carrier proteins SFRP2 or GPC4 were used.","affinity_potency":[],"species_and_systems":"Purified human proteins and HEK293 cells; adrenal context [PMID:39229119]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"bioRxiv preprint, not peer reviewed [PMID:39229119]. Binding was measured as transfer from a carrier, with no affinity value reported.","key_references":[{"PMID":"39229119","why":"WNT2B transferred to FZD3-CRD; non-canonical signalling"}],"covers":["LR003479","LR006679"]},"LR006688":{"pair":"WNT3 -> ROR2","headline":"Human Ror2 co-immunoprecipitates with Wnt3 and antagonises Wnt3 canonical signalling; binding does not activate Ror2.","interaction_type":"direct binding","direction_and_effect":"Ror2 physically interacts with Wnt3 and Wnt1 by immunoprecipitation; it antagonised Wnt3-mediated stabilisation of cytosolic beta-catenin and inhibited Wnt3 reporter activity, while potentiating Wnt1 reporter activity [PMID:15388793]. Neither ligand altered Ror2 autophosphorylation [PMID:15388793].","molecular_requirements":"Not reported in our evidence beyond Ror2 acting alone in osteoblastic cells.","affinity_potency":[],"species_and_systems":"Human Ror2 in osteoblastic cells [PMID:15388793]; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"Abstract only; immunoprecipitation does not show direct contact; no affinity. Effect is context-dependent (antagonist for Wnt3, opposite for Wnt1).","key_references":[{"PMID":"15388793","why":"Ror2 binds Wnt3 and antagonises it in osteoblasts"}],"covers":["LR003488","LR006688"]},"LR004987":{"pair":"WNT3 -> RYK","headline":"Wnt3 repels retinal axons via Ryk in a concentration-dependent manner, with Frizzled mediating attraction; functional in vivo evidence only.","interaction_type":"functional only","direction_and_effect":"Wnt3 repulsion of retinal ganglion cell axons is mediated by Ryk, whereas attraction at lower concentrations is mediated by Frizzled(s) [PMID:16280981]. Dominant-negative Ryk shifted axon termination zones medially [PMID:16280981].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Chick optic tectum and mouse superior colliculus; dossier labels ligand human and receptor mouse [PMID:16280981]. Human pair ortholog-inferred. Abstract only.","localisation_and_range":"Wnt3 forms a medial-lateral decreasing gradient in tissue, consistent with a diffusing guidance cue [PMID:16280981].","caveats":"Binding between Wnt3 and Ryk is not shown in the abstract. Outcome is concentration-dependent, repulsive via Ryk.","key_references":[{"PMID":"16280981","why":"Ryk-mediated Wnt3 repulsion in retinotectal mapping"}],"covers":["LR001598","LR004987"]},"LR004978":{"pair":"WNT3A -> FZD7","headline":"WNT3A binds the FZD7 cysteine-rich domain tightly and signals through FZD7 in a rescue system; one source is browser-read.","interaction_type":"direct binding","direction_and_effect":"WNT-3A showed strong binding (++++, KD < 10 nm) to the FZD4/5/7/8 CRDs [PMID:25605717]. Wnt3a induced signaling through a broad spectrum of FZD receptors in FZD-mutant cells [PMID:28733458].","molecular_requirements":"Binding was to FZD CRD-Fc fusions by bio-layer interferometry [PMID:25605717]. Cells with FZD1,2,7 mutated were unresponsive to canonical Wnts and were rescued by FZD/Wnt combinations [PMID:28733458].","affinity_potency":[{"value":"KD < 10 nm","assay":"Bio-layer interferometry, purified WNT-3A on FZD CRD-Fc, FZD4/5/7/8 grouped","system":"purified proteins","cite":"PMID:25605717"}],"species_and_systems":"Curation lists mouse proteins for PMID:25605717 and human for PMID:28733458 (HEK293T CRISPR mutants). Human and mouse versions of the pair are listed.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"The binding quote from PMID:25605717 is flagged in the curation notes as browser-read, unverifiable, spot-check pending. The KD bound covers FZD4/5/7/8 together, not FZD7 alone. PMID:28733458 was read as abstract only here.","key_references":[{"PMID":"25605717","why":"Bio-layer interferometry: strong WNT-3A binding to FZD CRDs"},{"PMID":"28733458","why":"Functional rescue map including FZD7"}],"covers":["LR001589","LR004978"]},"LR006697":{"pair":"WNT4 -> FZD1","headline":"WNT4-FZD1 rests on one co-IP result in mouse cells; UniProt says FZD1 is not clearly activated by WNT4.","interaction_type":"direct binding","direction_and_effect":"Co-IP found a Wnt4-Fzd1 binding complex [PMID:31216173].","molecular_requirements":"Complexes with LRP5 and LRP6 were also seen (Wnt4-LRP5, Wnt4-LRP6, LRP5-Fzd1) [PMID:31216173].","affinity_potency":[],"species_and_systems":"Co-IP in MC3T3 (mouse) cells, per curator note [PMID:31216173]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Result was browser-read and not spot-checked. UniProt says FZD1 is apparently not activated by WNT4 [DB:UniProt], so effect direction is uncertain.","key_references":[{"PMID":"31216173","why":"co-IP of Wnt4 with Fzd1 in MC3T3 cells"}],"covers":["LR003497","LR006697"]},"LR007669":{"pair":"WNT4 -> SFRP1","headline":"Supported only by a BioGRID record (BioGRID Reconstituted Complex); no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory ligand-ligand interaction [DB:BioGRID]. Direction not tested in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the BioGRID record.","localisation_and_range":"Both are secreted proteins [flag].","caveats":"No curator-verified paper; this is a ligand-ligand pair, not a receptor interaction.","key_references":[],"covers":["LR007669"]},"LR004996":{"pair":"WNT5A -> FZD8","headline":"Direct binding to the FZD8 cysteine-rich domain, shown by two bio-layer interferometry studies with purified mouse proteins.","interaction_type":"direct binding","direction_and_effect":"WNT5A binds FZD8 CRD with high affinity [PMID:25605717]; the curated modulatory effect is stimulatory (annotation). In the same 32D cell study, WNT-5A did not activate the WNT-beta-catenin pathway through FZD2/4/5 [PMID:25605717].","molecular_requirements":"Binding was to the FZD8 CRD (CRD-Fc fusion) alone; no co-receptor was needed for binding [PMID:20093360].","affinity_potency":[{"value":"KD = 50 nm","assay":"biolayer interferometry (Octet), Wnt5a binding to Fz8 CRD-Fc","system":"purified mouse proteins","cite":"PMID:20093360"},{"value":"KD = 4-8 nm","assay":"bio-layer interferometry, WNT-5A/5B binding to FZD8 CRD","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Both papers used mouse ligand and mouse receptor fragments in vitro; the human pair is ortholog-inferred in the interaction list.","localisation_and_range":"WNT5A is flagged secreted and FZD8 non-secreted [flag].","caveats":"Both papers were read as abstracts in our text field though the curator notes mention browser reading with unverified quotes. The two KD values differ about 10-fold between studies. Recombinant CRD binding, not full-length receptor in cells.","key_references":[{"PMID":"25605717","why":"Systematic WNT-FZD CRD binding map; KD 4-8 nm for WNT-5A to FZD8 CRD"},{"PMID":"20093360","why":"Wnt5a KD = 50 nm to Fz8 CRD"}],"covers":["LR001607","LR004996"]},"LR006778":{"pair":"Zp3 -> Zp3r","headline":"Mouse ZP3 egg-coat glycoprotein binds sperm sp56 (Zp3r) by crosslinking; one abstract-level study, direct binding.","interaction_type":"direct binding","direction_and_effect":"ZP3 is the egg protein recognised by sperm, and the ZP3 oligosaccharide crosslinked specifically to sp56, labelled an agonist-type recognition event by the curators [PMID:8188752]. The authors only suggest sp56 may be the sperm protein responsible for sperm-egg recognition in the mouse [PMID:8188752].","molecular_requirements":"The sperm-binding moiety is the ZP3 oligosaccharide, not the bare polypeptide [PMID:8188752]. Purified native sp56 eluted as a homomultimer (Mr approximately 110,000) of monomers with intramolecular disulfide bonds [PMID:8188752]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse sperm protein and mouse ZP3; purified native protein, ZP3 affinity chromatography, immunohistochemistry, immunoblotting and crosslinking [PMID:8188752].","localisation_and_range":"sp56 is a peripheral membrane protein on the outer surface of the sperm head plasma membrane, where sperm bind ZP3 [PMID:8188752]. ZP3 is an extracellular zona pellucida component around the egg, and is flagged secreted [flag]. This implies contact-dependent (juxtacrine) gamete recognition.","caveats":"Single paper; no affinity value reported in our evidence. The paper names the receptor sp56, and its mapping to Zp3r rests on the curators' notes. The conclusion is hedged (\"may be\"). Background on ZP3 affinity of sp56 comes from earlier work, not this paper. No database records.","key_references":[{"PMID":"8188752","why":"Purification and crosslinking show ZP3 oligosaccharide binds sperm sp56"}],"covers":["LR006778"]},"LR002011":{"pair":"SPX -> GALR2","headline":"Spexin activates GALR2 in a ligand-receptor study and mediates adipocyte effects via GALR2; two abstract-read papers.","interaction_type":"direct binding","direction_and_effect":"Spexin activates human, Xenopus and zebrafish GALR2/3 receptors but not GALR1 [PMID:24517231]. In adipocytes, spexin effects are mediated via GALR2 and GALR3 [PMID:30305242]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond the receptor itself; GALR3 is a companion receptor in the adipocyte study [PMID:30305242].","affinity_potency":[],"species_and_systems":"Human, Xenopus and zebrafish receptors in a ligand-receptor study [PMID:24517231]; murine 3T3-L1 and human adipocytes [PMID:30305242]. Mouse pair is listed as not projected.","localisation_and_range":"Spexin annotated as secreted; GALR2 as transmembrane [flag].","caveats":"Abstract-only reading. The ligand-receptor paper stresses GALR3 potency more than GALR2. The adipocyte paper is functional and does not show binding. UniProt also states spexin is a ligand for GALR2 and GALR3 [DB:UniProt][DB:GtoPdb].","key_references":[{"PMID":"24517231","why":"Spexin activates GALR2/3 but not GALR1"},{"PMID":"30305242","why":"Spexin effects on adipocytes mediated via GALR2/GALR3"}],"covers":["LR002011","LR005339"]}};